P.transport["npc:anastasia-hartwell"] = {
  hash = "b4d21f",
  fullHash = "c67820",
  text = "Anastasia Hartwell. Anastasia Hartwell is a prominent Forsaken mage trainer residing in the Magic Quarter of the Undercity. She guides fledgling and developing spellcasters in mastering the arcane arts and oversees vital magical research and field missions across Lordaeron and beyond. Standing within the dark, echoing chambers of the Undercity's Magic Quarter, Anastasia Hartwell instructs Forsaken and Horde mages in channeling arcane energies. Though the kingdom of Lordaeron fell to ruin, former human practitioners like Anastasia have preserved their scholarly traditions in undeath. She maintains that magic demands strict discipline, warning any traveler she meets that careless incantations will quickly consume the untrained. Beyond fundamental spell instruction, Anastasia directs promising students toward vital field investigations. She dispatches mages into Tirisfal Glades, including the blighted grounds of the Balnir Farmstead and ruined alchemist workshops, to recover lost reagents and salvage remnants of forgotten arcane lore. Through her tasks, practitioners learn that securing magical dominance requires braving the hazardous ruins of their former homeland. Anastasia's connections reach well beyond the borders of Tirisfal. As Horde spellcasters grow in proficiency, she coordinates with fellow trainers in distant lands, such as Deino in Orgrimmar, and directs advanced students toward solitary masters like Tabetha in the swamplands of Dustwallow Marsh. Her guidance ensures that Forsaken mages remain woven into the wider tapestry of the Horde's magical pursuits.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_anastasia-hartwell-9fdada84232175c45f0e/1-0000.mp3", duration = 95.477551, start = 0},
  },
}
P.transport["npc:aramis-hammerhand"] = {
  hash = "0e57d9",
  fullHash = "097c50",
  text = "Aramis Hammerhand. Aramis Hammerhand is an undead holy warrior situated within the desecrated chapel of Deathknell. As a Forsaken paladin trainer, he instructs newly risen dead who seek to reclaim their bond with the Holy Light. Walking this path in undeath requires immense discipline, as wielding such radiant energy inflicts agonizing pain upon their decayed flesh. Standing within the somber walls of Deathknell's chapel, Aramis Hammerhand represents an anomaly among the recently awakened Forsaken. In life, many citizens of Lordaeron answered the call of the Silver Hand, only to perish when the Scourge swept across the north. Aramis survived the fall only to be raised into undeath, yet he chose not to abandon the martial and spiritual teachings of his former existence. Now, he offers guidance to others who refuse to surrender their devotion. For an undead being, channeling the Holy Light is an ordeal of supreme willpower. The power burns necrotic flesh and reawakens long-dead nerves to excruciating pain. Aramis instructs his initiates that holding to this faith requires enduring continual torment. Through tasks like 'A Difficult Path' and 'Rediscovering the Light', he demands that young paladins confront the physical and spiritual costs of wielding a force inherently opposed to their present nature.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_aramis-hammerhand-77986bfcd9e9069ea01c/1-0000.mp3", duration = 77.7404082, start = 0},
  },
}
P.transport["npc:arugal"] = {
  hash = "b4d729",
  fullHash = "6486d8",
  text = "Arugal. Archmage Arugal is a former wizard of Dalaran and Gilneas who unleashed the feral worgen upon Lordaeron. Overcome by madness and grief, he now rules from the heights of Shadowfang Keep, treating the savage beasts as his beloved children while menacing all of Silverpine Forest. Before the fall of Lordaeron, Arugal was a member of the Kirin Tor, though some peers like Dalar Dawnweaver dismissed him as a charlatan whose weak spellcraft relied heavily on enchanted trinkets. When the Scourge swept across the north during the Third War, Arugal sought a weapon powerful enough to stem the tide. Drawing upon the esoteric research of the late Dalaran mage Ur, Arugal pierced the veil between realms and summoned the worgen into the mortal world. The ravenous beasts tore through the undead legions as intended, but their feral ferocity could not be contained, and their savage hunger swiftly turned against innocent mortals. The summoned horrors slaughtered the Gilnean soldiers stationed outside the Greymane Wall and spread their dreadful affliction through Gilneas. Some of the beasts then besieged the ancestral seat of Baron Silverlaine, and the keep fell swiftly to claws and fangs, its lord and retainers slain in the massacre. Rather than flee from his monstrous creation, Arugal's mind fractured under the weight of guilt, and he adopted the beasts as his own offspring. Renaming the fortress Shadowfang Keep, Arugal entrenched himself within its ramparts, surrounded by ghostly victims and loyal hound-packs.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_arugal-e6085b44055df71121c8/1-0000.mp3", duration = 90.122449, start = 0},
  },
}
P.transport["npc:baine-bloodhoof"] = {
  hash = "f3766e",
  fullHash = "369bb3",
  text = "Baine Bloodhoof. Baine Bloodhoof is the son of High Chieftain Cairne Bloodhoof and the acting protector of Bloodhoof Village in Mulgore. While his father governs the tribes from the towering heights of Thunder Bluff, Baine directly oversees local defense, investigating encroaching industrial exploitation and defending against feral predators. He serves as an essential bridge between youthful tauren braves and the ancestral wisdom of his clan. Born to Cairne and the late Tamaala, Baine spent his youth traveling alongside his nomadic people before they claimed the rich grasslands of Mulgore. His early life was marked by the ever-present threat of the centaur clans. Shortly after the Third War, a centaur warband under Khiragg captured young Baine, plunging Cairne into a grief-stricken stupor that nearly shattered the newly founded settlements. It was only through the courage of the champion Rexxar that Baine was liberated from captivity. That rescue restored Cairne's spirit, allowing the tauren to stand with Thrall's Horde against the invading Kul Tirans and secure their foothold on the continent. Rather than lingering in the relative comfort of the capital mesas, Baine chooses to reside among his kin in Bloodhoof Village. As Cairne advances in age, Baine carries an increasing burden of stewardship, representing the next generation of tauren leadership. He directs braves and visiting allies to combat the unruly Palemane gnolls who pester the borders, and keeps a watchful eye on suspicious outside influences threatening Mulgore's natural balance. Whenever Cairne departs the capital on state affairs, Baine steps forward as the acting leader for the united tribes. Beyond territorial border clashes, Baine faces modern encroachers unconcerned with spiritual balance. To the east, the goblin Venture Company cuts deep into the sacred landscape, while dwarven prospectors from Bael Modan dig into ancestral soil at the Bael'dun Digsite. Baine advocates for a firm yet measured response: attempting to warn the miners and destroy their destructive equipment rather than rushing into senseless bloodshed. He warns that the dwarves' violent digging is hurting the spirits of the earth, though the miners refuse to listen.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_baine-bloodhoof-0c7b8d2d29368141e2a7/1-0000.mp3", duration = 131.134694, start = 0},
  },
}
P.transport["npc:bethor-iceshard"] = {
  hash = "a5695c",
  fullHash = "d8984b",
  text = "Bethor Iceshard. Bethor Iceshard is a powerful Forsaken mage based in the Magic Quarter of the Undercity. Presiding over the arcane and shadow practitioners within the Temple of the Damned, he commands considerable authority in Sylvanas's realm. Beneath his chilly demeanor lies a past entwined with old friends torn apart by the Scourge. Standing within the Temple of the Damned, Bethor Iceshard oversees the practitioners of the arcane arts and shadow magic in the Undercity. Respected and feared for his intellect and icy resolve, Bethor wields sufficient political and magical weight to give direct instructions to provincial magistrates across Lordaeron. He directs agents of the Forsaken to secure valuable grimoires, investigate arcane anomalies, and stamp out rival powers that threaten the Undercity's dominion. Before the Third War devastated Lordaeron, Bethor was a mortal apprentice studying magic alongside two close companions: Gunther Arcanus and Thule Ravenclaw. As a testament to their fellowship, the three students wove their practice wands together. The Scourge shattered that bond entirely. When death and dark magic swept across the kingdom, Thule Ravenclaw willfully surrendered his soul to the Lich King, Gunther perished and rose on an isolated island in Brightwater Lake, and Bethor succumbed only to later break free as Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_bethor-iceshard-931be89a459dfcecd334/1-0000.mp3", duration = 79.6734694, start = 0},
  },
}
P.transport["npc:brewmaster-drohn"] = {
  hash = "04d8ab",
  fullHash = "db1f87",
  text = "Brewmaster Drohn. Brewmaster Drohn is an orcish brewmaster living just uphill from the bustling port of Ratchet. Having learned the art of exotic fermentation through ties connected to the legendary wandering pandaren Chen Stormstout, Drohn crafts potent beverages on the arid frontier of the Barrens. Adventurers who discover discarded kegs across Kalimdor often find themselves directed straight to his porch. Overlooking the goblin docks of Ratchet sits Brewmaster Drohn, an orc who has devoted his craft to the science of brewing rather than simple combat. Running Drohn's Distillery from his hillside home, he operates peacefully within the neutral haven established by Gazlowe's Steamwheedle cartel. While most orcs settle for coarse grog or simple spirits, Drohn's work involves rare ingredients, refined balances of flavor, and techniques rarely practiced among his kin. Drohn's craft is heavily shaped by Chen Stormstout, the famed pandaren wanderer who fought alongside Rexxar and the Horde during the founding of Durotar. Drohn's mentor studied directly under Chen, learning the guarded secrets of Stormstout brews, and Chen himself later instructed Drohn in crafting Trogg Ale. When travelers stumble across Chen's distinct, discarded kegs in the wilds, Drohn is the sole local authority capable of identifying the ingredients and recreating the wanderer's potent concoctions.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brewmaster-drohn-4ef60ffa3febe130dc0a/1-0000.mp3", duration = 84.7673469, start = 0},
  },
}
P.transport["npc:brine"] = {
  hash = "c7576d",
  fullHash = "a88505",
  text = "Brine. Brine is an orc shaman residing in the arid hills of Blackthorn Ridge in the southern Barrens. As an expert on the spirits of water, she guides shaman initiates along the spiritual path to commune with the tides and earn their Water Totem. Perched upon a windswept hill in northern Blackthorn Ridge, Brine lives far from the bustling trading posts of the Barrens. Despite the dry savannas surrounding her, she has dedicated her life to understanding the fluid and fickle element of water. Shaman across the Horde are directed to seek her wisdom once they have mastered earth and fire, for water requires patience and perspective that few understand as deeply as she does. In her younger years, Brine marched alongside her orc companions across the Hillsbrad Foothills, taking part in battles against human settlements. During that arduous campaign, she found herself in Tarren Mill, where she encountered a humble well fed by pure, fresh spring water. That well remained in her memory as a symbol of life persisting amidst devastation, reinforcing a lesson taught to her as a child: even in the darkest times of sorrow, a small token of hope can still be found.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_brine-24d2dcf89465aba1b449/1-0000.mp3", duration = 68.7804082, start = 0},
  },
}
P.transport["npc:cairne-bloodhoof"] = {
  hash = "5800f5",
  fullHash = "b733a6",
  text = "Cairne Bloodhoof. Cairne Bloodhoof is the venerable High Chieftain of the united tauren tribes and ruler of Thunder Bluff. A towering warrior of immense wisdom, he bound the fate of the tauren to Thrall's Horde after the orcs aided his people in escaping extinction at the hands of the centaur. For generations, the tauren lived as wandering nomads across the Barrens, continually hunted and driven toward extinction by savage centaur marauders. When Thrall and his orcs arrived on the shores of Kalimdor, Cairne recognized a rare nobility in them. Thrall offered military protection, escorting Cairne's desperate caravan across the plains to the safety of Mulgore in exchange for guidance to the Oracle at Stonetalon Peak. Settling upon the towering mesas of Thunder Bluff, Cairne finally established a permanent, unified home for all tauren tribes. Indebted to Thrall, Cairne followed the orcs to Stonetalon Peak and fought side by side with the Horde and Jaina Proudmoore's humans against the Burning Legion during the Third War. Later, when Admiral Daelin Proudmoore invaded Durotar, Cairne personally took up his ancestral runespear once more to fight alongside Rexxar after his captured son, Baine, was safely recovered. Today, Cairne stands as one of the Horde's most respected elders and Thrall's closest confidant, offering calm council against reckless warmongering.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_cairne-bloodhoof-9efeca7ffcec65a5a46f/1-0000.mp3", duration = 83.0955102, start = 0},
  },
}
P.transport["npc:canaga-earthcaller"] = {
  hash = "64c706",
  fullHash = "310f0a",
  text = "Canaga Earthcaller. Canaga Earthcaller is a Darkspear troll shaman stationed in the sunbaked Valley of Trials. He instructs novice Horde shamans in communing with the spirits of the land and obtaining their first elemental totems. Beyond ritual guidance, he keeps a watchful eye on wounded scouts and emerging threats near the Den. Perched on the red bluffs of the Valley of Trials, Canaga Earthcaller serves as one of the very first spiritual guides for Darkspear trolls and orcs who walk the path of the shaman. While many trainers focus strictly on martial readiness, Canaga teaches newcomers how to quiet their minds and listen to the rumblings of Kalimdor itself, preparing the earth sapta necessary to commune with the spirits. Before any fledgling shaman can truly channel the elemental fury of the earth, they must prove their respect and resolve to the spirits. Canaga directs initiates to gather sacred reagents and journey to the local spirit rock in Durotar. Through his guidance, novices drink the earth sapta, behold the elemental spirits firsthand, and earn their Earth Totem. Canaga does not merely dwell on esoteric rituals; he remains attuned to the valley's immediate dangers. When his friend Hana'zua heads north into the valley where the scorpids hunt and fails to return, Canaga directs capable travelers to search for him, ensuring the tribe's scouts are not left to perish in the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_canaga-earthcaller-0eecc0c0c11e45395b5d/1-0000.mp3", duration = 83.1738776, start = 0},
  },
}
P.transport["npc:chief-hawkwind"] = {
  hash = "9d1df3",
  fullHash = "76a931",
  text = "Chief Hawkwind. Chief Hawkwind is the tribal leader of Camp Narache, the proving grounds nestled in the Red Cloud Mesa of Mulgore. Responsible for guiding the youth of the Shu'halo, he mentors new adventurers as they embark on their traditional rites of passage. Under his watchful gaze, young braves learn humility, respect for the land, and the strength needed to protect their people. Standing at the heart of Camp Narache, Chief Hawkwind carries the solemn responsibility of preparing the next generation of tauren for the wider world. Red Cloud Mesa serves as a sheltered haven where fledgling hunters, shamans, druids, and warriors undertake the ancient Rites of the Earthmother. Hawkwind oversees these customs, ensuring that every youth learns duty and endurance before venturing beyond the safety of the mesa. Hawkwind's lessons begin with humility rather than martial glory. He sends initiates on simple chores, such as fetching clean spring water, to instill reverence for the natural world and their elders. Only after demonstrating a humble heart are braves guided toward tests of martial prowess, culminating in trials that test their resolve against the aggressive Bristleback quilboar encroaching upon the ancestral plains. Beyond his role as a mentor, Chief Hawkwind must reckon with rising dangers right at his camp's doorstep. The Bristleback tribe has grown increasingly bold, pressing hard against the perimeter of Red Cloud Mesa. Hawkwind coordinates the defense of the settlement, tasking newly proven braves with blunting the quilboar assaults to ensure the sacred training grounds remain secure.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_chief-hawkwind-9cba16ffab2522940835/1-0000.mp3", duration = 93.8057143, start = 0},
  },
}
P.transport["npc:coleman-farthing"] = {
  hash = "e6c443",
  fullHash = "8a1640",
  text = "Coleman Farthing. Coleman Farthing is a bitter Forsaken survivor residing in the Gallows' End Tavern in Brill. In life, he worked for the wealthy Agamand dynasty at their extensive flour mills in northern Tirisfal. Convinced to stay and defend the estate against the Scourge, he died alongside his fellow laborers, and now dedicates his undeath to exacting vengeance on his former masters. Before the Third War, Coleman Farthing earned an honest living as a laborer at the Agamand Mills, the largest milling and agricultural operation in Tirisfal Glades. When the Scourge poured across Lordaeron, the aristocratic Agamand family refused to flee their valuable lands. Instead, they urged their household and laborers to take up arms alongside them, promising they could hold the farmsteads against the undead horde. Coleman and his fellow workers stayed, believing their masters—a decision that cost every last one of them their lives. Raised into undeath only to break free under the banner of the Forsaken, Coleman harbors a burning hatred for the Agamands. Rather than blaming only the Scourge, he blames the sheer hubris and greed of his employers for tricking their staff into an impossible last stand. Now loitering in Brill's tavern, Coleman enlists Horde champions to march into the blighted mills, cut down the risen Agamand kin, and shatter the heirloom relics housed within their family crypt so that their legacy is utterly erased.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_coleman-farthing-ea023f9e6ad9b2386b6f/1-0000.mp3", duration = 85.7338776, start = 0},
  },
}
P.transport["npc:dalar-dawnweaver"] = {
  hash = "4185b6",
  fullHash = "0acc8b",
  text = "Dalar Dawnweaver. Dalar Dawnweaver is a former archmage of Dalaran who now serves the Forsaken at the Sepulcher in Silverpine Forest. Slain during the Scourge's destruction of the magi's city and later freed from the Lich King's control, he turns his magical intellect toward dissecting regional threats. From the shadows of the tomb, he directs efforts to understand Dalaran's lingering presence and undo the madness of Archmage Arugal. In life, Dalar Dawnweaver held high rank among the Kirin Tor, walking the halls of the Violet Citadel when Dalaran was a pinnacle of arcane mastery. His mortal life ended when the Scourge sacked the city to pave the way for Archimonde's summoning. Reanimated into the mindless thrall of the Lich King, Dalar broke free alongside Lady Sylvanas Windrunner when the Scourge's grip faltered. Now stationed at the Sepulcher, he retains the piercing intellect of an archmage, turned entirely toward safeguarding the Forsaken realm. Silverpine Forest is caught between multiple perils, and Dalar serves as the Sepulcher's arcane strategist. To the south, Dalaran wizards occupy Ambermill under a protective dome, meddling in matters Dalar seeks to uncover and disrupt. Even closer looms Shadowfang Keep and the feral worgen loosed upon the woods. Dalar possesses intimate knowledge of his former colleague, Archmage Arugal, and meticulously orchestrates campaigns to neutralize Arugal's beastly creations before they overrun the region.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dalar-dawnweaver-a9b9fef51e87a83888c2/1-0000.mp3", duration = 90.6187755, start = 0},
  },
}
P.transport["npc:darsok-swiftdagger"] = {
  hash = "6cf2c8",
  fullHash = "1b245e",
  text = "Darsok Swiftdagger. Darsok Swiftdagger is an orc warrior and scout stationed at the Crossroads in the heart of the Barrens. Known for his fierce hatred of harpies, he directs Horde adventurers north into the Dry Hills to break the avian matriarchy harassing travelers and settlements. He maintains ties across the plains, serving as a trusted contact for Witch Doctor Jin'Zil in Malaka'jin. Amid the bustling hub of the Crossroads, Darsok Swiftdagger keeps a sharp eye on the threats creeping out of the northern scrubland. The trade artery connecting Durotar, Mulgore, and the northern reaches is under constant siege, not only from raiders and centaur, but from organized aerial hunters. Darsok focuses his wrath on the Witchwing harpies, whose roosts in the Dry Hills northwest of the Forgotten Pools directly threaten northern caravans. While his immediate duties center around harpy eradication, Darsok Swiftdagger serves as an important point of contact within the Horde network. He maintains correspondence with Witch Doctor Jin'Zil, the enigmatic troll residing at Malaka'jin on the border of the Stonetalon Mountains. Messages and intelligence carried through Darsok help ensure that outlying enclaves stay informed of developments across the central plains.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_darsok-swiftdagger-5f2f83430b7dcd798f7e/1-0000.mp3", duration = 76.1469388, start = 0},
  },
}
P.transport["npc:deathguard-dillinger"] = {
  hash = "cf2185",
  fullHash = "f5d4af",
  text = "Deathguard Dillinger. Deathguard Dillinger is a Forsaken sentry stationed in Brill within Tirisfal Glades. Standing watch over the town's perimeter, he directs newly arrived undead toward necessary services and tasks recruits with keeping the local Scourge remnants at bay. As a member of the Forsaken Deathguard, Dillinger stands at the entrance of Brill, serving as both a frontline protector and an orienting guide for travelers emerging from Deathknell. He provides directions to town amenities such as the inn, the town hall, and local trainers, helping newly awakened undead navigate their new reality under the Dark Lady's rule. Dillinger actively enlists capable adventurers to purge lingering mindless Scourge from the nearby farms and mills. Through assignments like cullling rotting ghouls and reclaiming infested facilities, he seeks to establish a buffer zone of security around Brill, ensuring the fledgling Forsaken settlements can endure against unending undead predation.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_deathguard-dillinger-53a5710aad237e6b3ce6/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["npc:dendrite-starblaze"] = {
  hash = "e0e709",
  fullHash = "fe9e35",
  text = "Dendrite Starblaze. Dendrite Starblaze is a night elf druid residing in the sacred village of Nighthaven within Moonglade. Serving the Cenarion Circle, he acts as a vital mentor and guide for budding druids of both night elf and tauren descent. Through him, practitioners are summoned to the holy grove to master essential rites such as cleansing toxins and communing with nature's forms. Perched within Nighthaven, Dendrite Starblaze represents the nonpartisan, enduring spirit of the Cenarion Circle. When novice druids learn to attune their spirits to Teleport: Moonglade, Dendrite is among the first to welcome them upon arrival. He bridges the gap between ancient Kaldorei tradition and the emerging path of the tauren, treating all who heed the call of the wild as kin beneath the boughs of the sacred haven. Dendrite's primary duty involves initiating druidic apprentices into the deeper mysteries of nature. He directs novices through the trials required to understand poison and pestilence, sending them to examine tainted waters and discover herbal curatives. He also oversees the steps that lead druids to the water trials, testing their patience and endurance beneath the surface before granting communion with aquatic forms.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_dendrite-starblaze-dd613ea0cc6fbf9dcd10/1-0000.mp3", duration = 72.3853061, start = 0},
  },
}
P.transport["npc:devrak"] = {
  hash = "5e8cff",
  fullHash = "ff180e",
  text = "Devrak. Devrak is an orc wind rider master stationed at the Crossroads in the Barrens. Serving as the primary aerial conduit of central Kalimdor, he oversees the Horde's network of wyverns shuttling supplies and couriers between Durotar, Mulgore, and frontier outposts. He also ensures that crucial logistics, such as game meats and prepared hides, travel smoothly to the Horde's capitals. Positioned at the intersection of Kalimdor's major trade routes, Devrak tends the wyverns that keep the Horde unified across vast distances. The Crossroads sits exposed under the baking sun, vulnerable to quillboar, centaur, and Alliance scouts alike, making rapid aerial transit indispensable. Devrak handles both seasoned wayfarers and untested messengers, pairing riders with trained wind riders capable of crossing the savannah and reaching the mountain heights of Mulgore or the stone canyons of Durotar. Beyond ferrying travelers, Devrak plays a vital role in frontier logistics. The hunters of the Barrens harvest meat and pelts in abundance, which Devrak helps channel directly to the cooking fires of Orgrimmar and the tanners of Thunder Bluff. By introducing budding couriers to flight masters across the continents, he cements the aerial lifeline that feeds the Horde's heartlands. Flight masters in contested frontier territories cannot afford to be defenseless. Devrak is far more than a simple beast handler; when the Crossroads falls under attack, he calls upon enraged wyverns to tear into hostile intruders with venomous stingers and talons, making his roost a dangerous target for anyone bold enough to strike the settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_devrak-712d256a2d082295bc55/1-0000.mp3", duration = 101.564082, start = 0},
  },
}
P.transport["npc:eitrigg"] = {
  hash = "bc7729",
  fullHash = "78a7cb",
  text = "Eitrigg. Eitrigg is a seasoned veteran of the First and Second Wars who stands beside Warchief Thrall as an esteemed advisor in Orgrimmar. Once a high-ranking lieutenant of the Blackrock clan, he became disillusioned with the old demonic Horde and lived in exile until an extraordinary friendship with a human paladin changed his fate. Today, he helps guide the New Horde back to its roots of honor and shamanism. Born on Draenor into the Blackrock clan, Eitrigg was once one of Warchief Blackhand's primary lieutenants alongside Orgrim Doomhammer and Varok Saurfang. When Doomhammer seized leadership of the Horde, Eitrigg remained a trusted officer and oversaw the captured half-orc assassin Garona. Although he initially dismissed her revelations regarding Gul'dan and the demonic corruption of the Shadow Council, the horrific battles and ultimate defeat of the Horde in the Second War forced him to confront the dark reality. Sickened by the realization of how his people had been manipulated, Eitrigg walked away from the scattered remnants and retreated into self-imposed exile, seeking only solitude in the wilds of Lordaeron. Years into his wilderness exile, Eitrigg was discovered sheltering in an abandoned tower near Hearthglen by the human paladin Tirion Fordring. Their initial clash collapsed the ruins, but instead of finishing the unconscious human, Eitrigg pulled him from the rubble to safety. Moved by this display of pure martial honor, Tirion swore an oath of friendship and refused to betray the hermit's location. When the local Alliance authorities ultimately captured Eitrigg and sentenced him to hang in Stratholme, Tirion threw away his own knighthood, lands, and freedom in an attack to rescue the condemned orc. This legendary bond proved to both warriors that honor transcended the bitter hatred between their species. During Tirion's desperate attempt to free Eitrigg in Stratholme, Thrall's newly united Horde raided the city and extracted the aging warrior. Meeting Thrall convinced Eitrigg that the orcs were throwing off the demonic taint and rediscovering their ancestral shamanic heritage. Returning with Thrall across the Great Sea to Kalimdor, Eitrigg took up a revered post in the Valley of Wisdom within Orgrimmar. He now stands inside Grommash Hold as an advisor to the young Warchief, helping evaluate new recruits and imparting his hard-earned wisdom so that the New Horde never repeats the tragedies of the past.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_eitrigg-6a40c8fc132835be60be/1-0000.mp3", duration = 143.621224, start = 0},
  },
}
P.transport["npc:executor-arren"] = {
  hash = "659b25",
  fullHash = "842f4b",
  text = "Executor Arren. Executor Arren is a high-ranking Forsaken officer stationed in Deathknell. He oversees the immediate defense and consolidation of the settlement as newly awakened undead emerge from their graves. Arren coordinates the local campaign against mindless Scourge zombies, feral beasts, and the encroaching zealots of the Scarlet Crusade. Standing resolute just outside the chapel in Deathknell, Executor Arren serves as the primary military voice for the nascent Forsaken within their awakening grounds. While the caretakers in the crypts guide newly raised undead through their disorientation, Arren directs their focus outward toward survival. Under Queen Sylvanas Windrunner's banner, he organizes local operations to sweep away mindless zombies that threaten the village borders, establishing secure territory in the shadow of Lordaeron's fall. Deathknell is surrounded by perils far deadlier than confused fledglings. Under Arren's orders, scouts and initiates strike at the vicious arachnids inhabiting Night Web's Hollow and eliminate dangerous predators haunting the woodland fringes. By demanding decisive action from every capable hand, Arren tests the fortitude of new arrivals, ensuring only those capable of defending their second chance at existence remain in the service of the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_executor-arren-caf8003e68ecad93afa6/1-0000.mp3", duration = 78.2106122, start = 0},
  },
}
P.transport["npc:executor-zygand"] = {
  hash = "4fb161",
  fullHash = "b99af6",
  text = "Executor Zygand. Executor Zygand is a senior Forsaken commander stationed at the town hall in Brill, overseeing defensive and military operations across central Tirisfal Glades. Reporting directly to the Undercity's high command, he coordinates the purge of Scarlet Crusade forces pressing into Forsaken territory. Positioned at the administrative heart of Brill, Executor Zygand coordinates regional defense for the Forsaken after their initial awakening in Deathknell. Serving as the direct superior to regional officers like Executor Arren and field sentries such as Deathguard Linnea, Zygand synthesizes scout intelligence and dispatches able recruits to safeguard Lordaeron's borders from encroachment. Zygand's primary military concern is the fanatic presence of the Scarlet Crusade, which infests outposts across Tirisfal Glades. Under his direction, agents are sent systematically to strike at Crusader scouts, encampments, and forward bases, ensuring the zealots never muster sufficient strength to threaten the approaches to the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_executor-zygand-5a5011bc938228b78a25/1-0000.mp3", duration = 62.2236735, start = 0},
  },
}
P.transport["npc:gan-rul-bloodeye"] = {
  hash = "601fb2",
  fullHash = "673663",
  text = "Gan'rul Bloodeye. Gan'rul Bloodeye is a senior orc warlock trainer residing deep within the dark cavern of the Cleft of Shadow in Orgrimmar. Hidden away from the watchful gaze of the city above, he initiates Horde warlocks into darker demonic rites. Under his instruction, initiates learn to bend otherworldly entities like voidwalkers and succubi to their will. While Warchief Thrall tolerates the presence of warlocks in the new Horde, their dark arts are not welcomed in the open sunlight of Durotar. Gan'rul Bloodeye makes his home in the Cleft of Shadow, a subterranean refuge beneath Orgrimmar where shadow weavers, rogues, and fel casters can study unmolested. From this subterranean perch, Gan'rul serves as a primary tutor for rising practitioners of fel magic. Gan'rul's primary duty is overseeing the dangerous summoning rituals required of ambitious warlocks. Practitioners seeking to bind greater demons—such as the resilient voidwalker or the seductive succubus—must consult Gan'rul to secure ritual components and learn the precise incantations needed to dominate the summoned creature before it consumes its master.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gan-rul-bloodeye-dbd3ad89c5b39d4e9ff1/1-0000.mp3", duration = 69.7469388, start = 0},
  },
}
P.transport["npc:gazrog"] = {
  hash = "7eb672",
  fullHash = "60499f",
  text = "Gazrog. Gazrog is an orc warrior stationed at the Crossroads in the heart of the Barrens. Tasked with maintaining logistics and security along the savannah's perilous roads, he recruits able Horde travelers to deal with regional threats and investigate lost patrols. The Crossroads serves as the vital junction for all Horde transit through Kalimdor, but its isolation leaves supply lines vulnerable to marauders and beasts alike. Gazrog stands watch alongside the settlement's defenders, working to ensure that cargo, coin, and couriers reach their destinations. Maintaining order in a sprawling wilderness requires constant vigilance, and Gazrog relies heavily on passing adventurers to handle crises brewing beyond the outpost's stockades. Between predatory raptors harassing trails and aggressive quillboar clans ambushing scouts, Gazrog's duties never end. He frequently coordinates responses to highway robberies—such as retrieving stolen Horde shipments—and keeps track of missing soldiers like the grunt Dogran, who ended up an injured prisoner of the quilboar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gazrog-d8b9d2d975427021698c/1-0000.mp3", duration = 65.5934694, start = 0},
  },
}
P.transport["npc:gornek"] = {
  hash = "49e14c",
  fullHash = "aad15d",
  text = "Gornek. Gornek is an orc overseer stationed in the Valley of Trials in Durotar. He serves as the primary point of intake for fresh orc and Darkspear troll recruits preparing to prove their worth to the New Horde. Standing directly at the heart of the Valley of Trials, Gornek represents the initial test of discipline for aspiring Horde warriors, scouts, and spellcasters. Under Warchief Thrall's order, every youth and newcomer must earn their place through grit and perseverance rather than entitlement. Gornek assesses those stepping into the valley, reading their introductory orders and directing them to trainers throughout the compound. Whether an initiate carries an encrypted scrawl, a glyphic parchment, or a simple tablet, it is Gornek who receives their credentials and sets them upon their harsh path of survival. The arid canyons of the valley test more than battle prowess; they instill the communal ethos of the New Horde. Gornek ensures that novices do not linger aimlessly, pointing them toward the trials of the nearby scorpid burrows, the dens of feral boars, and the watchful eyes of veteran instructors. For those who survive the training grounds and slay the threats lurking in the red rock gullies, Gornek offers the final acknowledgment before dispatching them outward into the wider, perilous landscape of Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gornek-c6f4fbe3bea73cfa80b1/1-0000.mp3", duration = 78.7853061, start = 0},
  },
}
P.transport["npc:gunther-arcanus"] = {
  hash = "aaccd3",
  fullHash = "ae85b0",
  text = "Gunther Arcanus. Gunther Arcanus is an exceptionally powerful necromancer dwelling on an isolated island in Brightwater Lake. Slain during the Third War and raised into undeath, he managed to shatter the Lich King's mental grip entirely on his own. Long believing he was the sole undead possessing free will, he defended his retreat against all outsiders until discovered by the Forsaken. Before the fall of Lordaeron, Gunther was a promising apprentice among the Kirin Tor in Dalaran. Alongside close friends Bethor Iceshard and Thule Ravenclaw, he studied the arcane arts, secretly delving into necromancy despite the Kirin Tor's strict prohibitions against dark magic. To commemorate their brotherhood, the trio once bound their apprentice wands together into a single heirloom. When the Scourge swept across the north during the Third War, Gunther perished to the Plague of Undeath and was raised into servitude. Unlike most who required the Lich King's power to weaken or Lady Sylvanas to break their chains, Gunther's raw arcane mastery and sheer willpower allowed him to shake off the Lich King's mental domination entirely by himself. Convinced that every other walking corpse remained a mindless thrall of the Scourge, he retreated to an island in Tirisfal Glades, surrounding himself with shambling guardians and cutting off all contact with the living and dead alike.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_gunther-arcanus-c8dfa8b3ba1bfb53fec7/1-0000.mp3", duration = 83.7485714, start = 0},
  },
}
P.transport["npc:islen-waterseer"] = {
  hash = "442247",
  fullHash = "426d80",
  text = "Islen Waterseer. Islen Waterseer is a respected tauren shaman who dwells beside a quiet fishing hut on the Tidus Stair, overlooking the eastern sea of the Barrens. Possessing an intimate communion with the spirits of water, she guides initiates on the trials necessary to attune with the element. Novice shamans across the Horde seek her wisdom to earn their Water Totem. Far from the bustling crossroads and encampments of the Barrens, Islen Waterseer lives along the craggy coastline known as the Tidus Stair. Here, where the arid plains break against the Great Sea, the presence of the water spirits is raw and pervasive. Rather than dwelling in thunderous halls or busy cities, Islen prefers this quiet outpost, dedicating her days to listening to the tides and assisting shamans who seek communion with the fluid element. Understanding water requires more than simple study; it demands internal harmony and spiritual perception. Islen guides seekers through the preparation of the Water Sapta, a sacred brew that pierces the veil between mortal senses and elemental manifestations. Her teachings remind shamans that water is as unyielding and deep as it is fluid and restorative, requiring immense respect from any who hope to call upon its aid. While Islen maintains a quiet life on the coast, her spiritual reach and connections extend across Kalimdor. She maintains a close, enduring friendship with Greta Mosshoof, another wise tauren versed in the restorative arts. Through these connections, Islen's knowledge of water's purifying essence touches matters well beyond the Barrens, even offering spiritual aid to lands afflicted by deep corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_islen-waterseer-60bc2800a858fa5e8300/1-0000.mp3", duration = 98.0897959, start = 0},
  },
}
P.transport["npc:kadrak"] = {
  hash = "5a62d3",
  fullHash = "449018",
  text = "Kadrak. Kadrak is a seasoned orc commander stationed at the Mor'shan Rampart on the border between the Barrens and Ashenvale. Tasked with safeguarding the northern frontier, he coordinates the flow of dispatches and reinforcements into the contested forest. For Horde adventurers pushing past the arid plains, Kadrak serves as the gateway to the ongoing struggle against the night elves. Standing atop the fortified timber barricades of the Mor'shan Rampart, Kadrak watches over the primary route connecting the Barrens to Ashenvale. The border is a precarious frontier: to the south lie the sun-scorched plainsclaimed by the Horde, while to the north loom the ancient woods guarded fiercely by the night elves. Kadrak ensures that the defensive perimeter remains unbroken against encroaching Sentinels and hostile woodland creatures. Beyond holding the line, Kadrak manages essential military intelligence between the Barrens and the forward logging camps deeper in the forest. He receives couriers bearing critical combat reports from the Warsong Outriders and coordinates the movement of supplies and fresh blood into outpost hubs like Splintertree Post. Those reporting to him are promptly directed into the heart of the territorial war.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_kadrak-b1a9b2206bbf7620de2a/1-0000.mp3", duration = 70.5567347, start = 0},
  },
}
P.transport["npc:thork"] = {
  hash = "b4da80",
  fullHash = "06d370",
  text = "Thork. Thork is an orc warrior stationed at the Crossroads who oversees the settlement's local defenses. Charged with securing the bustling crossroads of the Barrens, he directs Horde adventurers to push back raiders and secure vital supply lines. The Crossroads serves as the beating heart of Horde transit in Kalimdor, connecting Durotar, Mulgore, and the wilds beyond. Holding it is no easy feat. Thork shoulders the responsibility of defending the town from constant external pressures. Between quillboar raids, centaur aggression, and marauding harpies, his forces are stretched thin, forcing him to rely on capable travelers and emerging champions to handle critical security tasks. Thork's duties extend well beyond the walls of the Crossroads itself. He coordinates defense efforts along vital supply corridors, dispatching scouts and liaisons north toward the Mor'shan Rampart to report directly to Kadrak. Keeping these northern and eastern arteries open is essential to sustaining the Horde's presence in the harsh and unforgiving scrublands of the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_npc_thork-3adc45fdb8f255516229/1-0000.mp3", duration = 64.1306122, start = 0},
  },
}
P.transport["subzone:agama-gor"] = {
  hash = "979eca",
  fullHash = "689e8e",
  text = "Agama'gor. Agama'gor is a major Bristleback quilboar encampment situated in the southern Barrens, nestled just north of the road leading west toward Mulgore from Camp Taurajo. It represents a constant thorn in the side of the nearby Horde outpost, teeming with hostile quilboar fiercely clinging to their rugged territory. Sprawling across the dusty plains of the southern Barrens, Agama'gor serves as a fortified settlement for the aggressive Bristleback tribe of quilboar. Located dangerously close to Camp Taurajo, the quilboar here maintain a dense network of brambles, huts, and crude totems. Their heavy presence poses an active threat to travelers moving between the Barrens and the grassy hills of Mulgore, prompting Horde scouts and hunters to wage a perpetual war of containment against them. Beyond the general animosity between the Horde and the quilboar, Agama'gor is a prime source of the mysterious, crimson stones known as Blood Shards. Found on the Bristleback inhabiting this village, these geomantic minerals are prized by Mangletooth, a quilboar exile held captive at Camp Taurajo. Driven by ancient beliefs tied to Agamaggan's sacred essence, adventurers often raid Agama'gor to harvest these shards and trade them for potent tribal charms.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_agama-gor-518b0e6ad677d0d74d87/1-0000.mp3", duration = 76.3036735, start = 0},
  },
}
P.transport["subzone:agamand-mills"] = {
  hash = "6bc02f",
  fullHash = "c57dd3",
  text = "Agamand Mills. Agamand Mills is a sprawling farm and windmill complex nestled in the northern heights of Tirisfal Glades. Once the proud estate of the wealthy Agamand dynasty, it has fallen into ruin and stands as the largest Scourge stronghold in the region. Centuries ago, wealthy noble immigrants from Strom established the Agamand estate, building a vast milling network across northern Tirisfal. When the Third War broke out and the Scourge swept across Lordaeron, the patriarch Gregor Agamand refused to flee, fortifying the compound and convincing his retainers and laborers to make their stand. Their provisions and stone walls might have held, but their youngest son, Devlin Agamand, betrayed his blood. Devlin slaughtered the estate watchmen and let the walking dead into the sleeping quarters. Crippled from within, the remaining defenders were wiped out, and the family joined the mindless ranks of the undead. Today, the Agamand Mills are the most entrenched bastion of the Scourge in Tirisfal Glades, posing an immediate threat to the Forsaken realm. The rotting windmills now churn above infested fields of wights, zombies, and skeletal horrors. Beneath the estate, Captain Dargol commands the garrison from the deep Agamand Family Crypt, practicing necromancy to reanimate generations of Agamand ancestors. From Brill, Magistrate Sevren and the Deathguards wage an active campaign to clear the mills and purge the Scourge presence before it can march upon the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_agamand-mills-c1c149b241ab58f1e80e/1-0000.mp3", duration = 90.6971429, start = 0},
  },
}
P.transport["subzone:ambermill"] = {
  hash = "dab7a5",
  fullHash = "3be2e6",
  text = "Ambermill. Ambermill is a fortified human settlement in central Silverpine Forest, situated just southwest of Lordamere Lake. Originally a Gilnean lumber village, it is now occupied by surviving wizards and apprentices of Dalaran. Their presence represents a dangerous outpost of human resistance on the southern borders of the Forsaken realm. Before the Third War, Ambermill was a quiet lumber town on lands owned by the Gilnean nobleman Darius Crowley. When King Genn Greymane erected the Greymane Wall to seal his kingdom away, Ambermill was left stranded outside alongside Pyrewood Village. In the chaotic aftermath of Lordaeron's fall, the surviving wizards of the Kirin Tor moved in and fortified the settlement. Dalaran spellscribes, conjurors, and apprentices now patrol its buildings and stables, using Ambermill as a forward redoubt against the undead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_ambermill-b27010d7668e15d52b3f/1-0000.mp3", duration = 54.804898, start = 0},
  },
}
P.transport["subzone:apothecarium"] = {
  hash = "47efe4",
  fullHash = "84c0ea",
  text = "Apothecarium. The Apothecarium is the southwestern quarter of the Undercity and the headquarters of the Royal Apothecary Society. Within these noxious laboratories, Forsaken alchemists labor tirelessly under Master Apothecary Faranell to concoct virulent plagues, toxins, and engineered horrors. It stands as the grim heart of Undercity's biological research, vital to Lady Sylvanas's campaign against the living and the Scourge. Occupying the southwestern terrace of the subterranean capital, the Apothecarium is a labyrinth of bubbling vats, dissection tables, and pungent chemical fumes. Led by Master Apothecary Faranell, the Royal Apothecary Society utilizes this district to advance their understanding of mortality and rot. Here, alchemists and surgeons experiment on tissue grafts, vivisection, and the assembly of mighty abominations. Their overriding purpose, mandated by Lady Sylvanas Windrunner, is the formulation of a new plague capable of eradicating both the Scourge and the lingering human presence across Lordaeron. Beyond grand military ambitions, the quarter serves as the premier center of practical alchemy and herbalism for the Horde in the Eastern Kingdoms. Initiates and masters alike gather beside toxic canals to distill concoctions, study botanical blights, and consult master practitioners.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_apothecarium-c8fd1c026736f470a313/1-0000.mp3", duration = 83.2, start = 0},
  },
}
P.transport["subzone:bael-dun-digsite"] = {
  hash = "1da3fe",
  fullHash = "9f6fb8",
  text = "Bael'dun Digsite. The Bael'dun Digsite is a dwarven excavation carved deep into the mountains along the western edge of Mulgore. Established by Prospector Khazgorm's team out of Bael Modan, the quarry is viewed by the local tauren as a direct desecration of their ancestral homeland and an insult to the Earth Mother. Perched on the mountain slopes of western Mulgore, the Bael'dun Digsite represents the southernmost reach of the dwarven Explorers' League expedition based out of Bael Modan in the southern Barrens. Unconcerned with territorial borders or the spiritual traditions of the newly settled tribes, dwarven prospectors arrived with picks, shovels, and blasting powder to unearth ancient Titan relics buried beneath the plains. The Bloodhoof tribe viewed this invasive quarrying as an outright assault on the Earth Mother. Baine Bloodhoof initially urged caution and attempted to warn the interlopers away, but the dwarves flatly refused to abandon their trenches. Concluding that diplomacy had failed, the tauren resolved to break the expedition's tools and forcibly expel the miners before their destructive digging tears further into Mulgore's sacred earth.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bael-dun-digsite-6ee51fb239f070dca31d/1-0000.mp3", duration = 68.4669388, start = 0},
  },
}
P.transport["subzone:bael-dun-keep"] = {
  hash = "6ce2f8",
  fullHash = "6cfda8",
  text = "Bael'dun Keep. Bael'dun Keep is an imposing dwarven fortification overlooking the Bael Modan excavation in the southern Barrens. Under the command of General Twinbraid, this fortress anchors the Alliance's controversial presence in the region, bringing them into violent conflict with the surrounding Horde territories. Constructed according to designs by the dwarven architect Haggis Boatmurder, Bael'dun Keep serves as the fortified military heart of the Ironforge presence in the southern Barrens. Towering over the expansive excavation trenches of Bael Modan, the fortress protects the Prospectors and archaeologists searching for ancient titan artifacts. Heavily armed with ironworks and artillery, its garrison maintains a vigilant watch, securing dwarven supply lines and projecting Alliance martial power straight into Kalimdor's heartland. The construction of Bael'dun Keep and the adjoining digsite did not come peacefully; it displaced the local Stonespire tribe of tauren from their ancestral home. Now, Bael'dun sits as a simmering flashpoint in the Barrens. Nearby Horde outposts view the fortress as a flagrant military intrusion, while Gann Stonespire wages a personal war of vengeance against the invaders. Between aggrieved tauren, opportunistic scouts, and suspicious outposts like Camp Taurajo, the keep is constantly under threat of raid and sabotage.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bael-dun-keep-0c9b183ab7e5e1958253/1-0000.mp3", duration = 81.8155102, start = 0},
  },
}
P.transport["subzone:balnir-farmstead"] = {
  hash = "542d38",
  fullHash = "20bbe2",
  text = "Balnir Farmstead. The Balnir Farmstead is a derelict estate in eastern Tirisfal Glades, northeast of the Ruins of Lordaeron. Once renowned for raising the famed white horses favored by Lordaeron's royal family, the lands now lie ruined and infested by wandering Scourge. Today, the estate stands as a somber monument to Prince Arthas Menethil's early life and the site where he claimed his undead steed. For generations, the Balnir family bred the legendary white stallions of Lordaeron from their homestead in the rolling hills of Tirisfal. As a boy, Prince Arthas Menethil frequently visited the farm to escape royal court life, befriending the young Jarim Balnir. It was here that Arthas assisted in the foaling of the colt he named Invincible. Years later, after a tragic riding accident claimed the steed's life, Invincible was laid to rest in the soil of the farmstead upon Arthas's personal request. When Prince Arthas returned from Northrend and sacked Capital City, the Scourge wiped out the Balnir family without mercy. Newly fallen as a death knight, Arthas marched to the farmstead to exhume and resurrect Invincible with Frostmourne, leaving behind an open, ransacked grave. In the wake of the Third War, the ruins serve as a foothold for mindless Scourge slipping past the Bulwark. Forsaken deathguards watch the farm warily, while Undercity magi harvest surviving snapdragons from the garden to test how deeply plague corruption has crept into the soil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_balnir-farmstead-ab89223807a486c4a177/1-0000.mp3", duration = 90.8538776, start = 0},
  },
}
P.transport["subzone:bandarion-keep"] = {
  hash = "99d14c",
  fullHash = "3bdf1f",
  text = "Bandarion Keep. Bandarion Keep is a fortified redoubt associated with Tyr's Watch, nestled in the western reaches of Tirisfal Glades near the Whispering Forest. Named in honor of Garek Bandarion, the outpost serves as an isolated bulwark amidst lingering threats across the woodland frontier. Its defenders contend with everything from hostile coastal murlocs to roving zealots and unstable undead. Situated near the secluded Whispering Forest in western Tirisfal Glades, Bandarion Keep stands as a solitary sentinel for the Forsaken. Named after Garek Bandarion, this stronghold is closely tied to Tyr's Watch. Quartermasters like Jorin Croge work diligently to keep the garrison supplied despite its remote and challenging position far from the bustling courtyards of the Undercity. Holding the keep is no quiet assignment. The outpost faces constant danger from Vile Fin murloc raids along nearby waters, probing skirmishes by the Scarlet Crusade, and stray, mindless Scourge thralls shambling through the gloom. Worse still are internal perils: certain paladins struggling to adjust to their unlife as Forsaken have succumbed to madness, turning their weapons against their own kindred.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bandarion-keep-a67d75dfb5164901759e/1-0000.mp3", duration = 71.4971429, start = 0},
  },
}
P.transport["subzone:blackthorn-ridge"] = {
  hash = "73ae91",
  fullHash = "20e200",
  text = "Blackthorn Ridge. Blackthorn Ridge is a jagged, bramble-choked valley tucked away in the southern reaches of the Barrens, immediately north of Razorfen Kraul. The area crawls with aggressive Razormane quilboar guarding their thorny settlements. High on the ridge above sits the camp of the orc shaman Brine, watching over an unusually pure pool of mountain water. Nestled near the towering burls of Razorfen Kraul, Blackthorn Ridge is dominated by dense thickets of massive, sharp briars. The Razormane quilboar consider these grounds ancestral territory, using the natural barricades to ambush outsiders and stage skirmishes into the southern Barrens. Despite the constant danger, travellers seek out the ridge for the hermit orc shaman Brine, who tends a camp perched above a spring noted across Kalimdor for its remarkable clarity and spiritual purity.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_blackthorn-ridge-16e16d054b07eac7f2f2/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["subzone:bladefist-bay"] = {
  hash = "b75c90",
  fullHash = "fe7a1e",
  text = "Bladefist Bay. Bladefist Bay is the rugged stretch of coast lining eastern Durotar just outside the gates of Orgrimmar. Named in honor of Kargath Bladefist, the bay serves as a natural harbor facing the Great Sea, shadowed by craggy bluffs and the nearby southern shores of Azshara. Stretching along the northeastern edge of Durotar, Bladefist Bay opens directly into the vast waters of the Great Sea. Flanked by rocky cliffs and treacherous surf, it functions as a primary maritime threshold for the Horde capital of Orgrimmar. The tides frequently deposit driftwood, ocean refuse, and flotsam onto the coastline, earning it a reputation among locals as a natural collection point for ocean debris. Directly north, the ancient red cliffs and ruins of Azshara loom across the water, making the bay a vital maritime boundary for Durotar. The bay honors Kargath Bladefist, the famed chieftain of the Shattered Hand clan who severed his own hand to replace it with a blade during the old Horde's trials on Draenor. The proximity of the bay to places like Skull Rock—where cultists and hidden rogue networks operate in the shadows—echoes the fierce and ruthless legacy of the clan whose chieftain gave the waters their name.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bladefist-bay-b8c44193ea08febb3856/1-0000.mp3", duration = 74.5534694, start = 0},
  },
}
P.transport["subzone:bloodhoof-village"] = {
  hash = "0fb75e",
  fullHash = "bc9163",
  text = "Bloodhoof Village. Bloodhoof Village is a central tauren settlement resting along the banks of Stonebull Lake in Mulgore. Named in honor of the Bloodhoof tribe, it serves as the first major gathering hub for young hunters and braves journeying out from Camp Narache toward Thunder Bluff. Led by Baine Bloodhoof, the village coordinates local defense, trade, and traditional rites across the plains. Situated around the clear waters of Stonebull Lake, Bloodhoof Village is a bustling center of commerce, craft, and ceremony in central Mulgore. Young tauren departing their trials at Camp Narache arrive here to hone their skills before venturing onward to the great mesas of Thunder Bluff. It is also well-known across Kalimdor for its master drum makers and the patient breeders who tame wild kodo beasts for travel. Day-to-day governance and the defense of the region fall under Baine Bloodhoof, son of High Chieftain Cairne Bloodhoof. Under his watchful eye, braves are dispatched to secure the grasslands against aggressive wildlife, quilboar encroachers, and the shadowy presence of the Venture Company. Alongside Baine, spiritual guides such as Zarlman Two-Moons tend to the inner life of the tribe, directing novices through sacred journeys like the Rite of Vision.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bloodhoof-village-85e098afc31ce6eeb955/1-0000.mp3", duration = 73.8220408, start = 0},
  },
}
P.transport["subzone:boulder-lode-mine"] = {
  hash = "bb8084",
  fullHash = "4736e5",
  text = "Boulder Lode Mine. Boulder Lode Mine is an aggressive excavation cut into the hills of the northeastern Barrens. Though orcish banners and watchtowers suggest the Horde first established the site, it is now firmly seized and operated by the ruthless Venture Company. The presence of weathered orcish architecture around the mouth of Boulder Lode Mine indicates that the Horde once held or founded the claim. Today, however, the area crawls with Venture Company overseers and enforcers working under the direction of Boss Copperplug. The goblin syndicate strip-mines the canyon with little regard for the local ecosystem or their workers, driven purely by the search for valuable minerals, high-yield gems, and industrial machinery. Word of the riches pulled from Boulder Lode Mine has reached outside ears in Ratchet. Wharfmaster Dizzywig has dispatched mercenaries to pocket a rumored massive emerald unearthed in its tunnels, while engineers seeking to understand complex goblin machinery know Boss Copperplug keeps key operational manuals hidden away within his camp.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_boulder-lode-mine-beec4c0efdbf27903f0c/1-0000.mp3", duration = 61.5183673, start = 0},
  },
}
P.transport["subzone:bramblescar"] = {
  hash = "319923",
  fullHash = "bc15c0",
  text = "Bramblescar. Bramblescar is a heavily fortified Razormane quilboar settlement situated in the southern Barrens. Thick, thorny brambles shield the encampment as its inhabitants wage a brutal war against the rival Bristleback tribe across the Gold Road. Carved into the jagged, giant briars of the southern Barrens, Bramblescar serves as a vital redoubt for the Razormane quilboar. These defensive brambles grow thick and sharp enough to deter casual wanderers, but the quilboar within are far from peaceful. Fiercely territorial and hostile to outsiders, they mount continuous skirmishes against anyone who ventures near their borders, viewing all non-quilboar as intruders upon land blessed by their ancient boar gods. Bramblescar sits in perpetual tension directly across the Gold Road from Agama'gor, an encampment held by the rival Bristleback tribe. The two factions are locked in an unrelenting tribal war for dominion over the southern Barrens. Between fighting off Horde travelers along the highway and repelling Bristleback raiding parties, the Razormane warriors of Bramblescar remain on constant, violent alert.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_bramblescar-969c015a2d1ccf786460/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["subzone:brill"] = {
  hash = "7657f6",
  fullHash = "9c997a",
  text = "Brill. Brill is the primary Forsaken settlement in the heart of Tirisfal Glades, situated just north of the Ruins of Lordaeron. Once a prosperous human town, it now serves as the administrative and military hub for newly awakened undead stepping beyond the confines of Deathknell. Before the Third War, Brill was a lively village under the sway of regional nobles such as the Barov and Agamand families. That prosperity ended when Kel'Thuzad chose the area for the Cult of the Damned's earliest experiments with the Plague of Undeath. The devastating blight swept through the population so quickly that local militia were driven out, leaving a sprawling mass graveyard in its wake.\n\nNow rebuilt by the Forsaken under the leadership of Magistrate Sevren, the town retains its weathered Lordaeron architecture beneath an atmosphere of grim purpose. Brill functions as the regional command center, coordinating defenses against Scarlet Crusade incursions, roaming Scourge remnants, and native beasts warped by necromantic decay. Beyond local defense, Brill is an essential crossroads linking Tirisfal Glades to the wider Horde. Overhead, the goblin-operated zeppelin tower provides transit south toward Durotar and deep into Stranglethorn Vale. Within the settlement, Gallows' End Tavern serves not only as a dark shelter for travelers, but also as a makeshift laboratory where captured Scarlet zealots are interrogated and subjected to apothecarial testing.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_brill-38d027f2a25fbba02f67/1-0000.mp3", duration = 86.2040816, start = 0},
  },
}
P.transport["subzone:burning-blade-coven"] = {
  hash = "4cc8e8",
  fullHash = "62025a",
  text = "Burning Blade Coven. Tucked into the northern cliffs of the Valley of Trials, the Burning Blade Coven is an infested cave network threatening the Horde's newest recruits. Corrupted cultists and summoned demons lurk within, turning an old mineral cavern into a staging ground for dark magic right on Durotar's doorstep. The dusty red mountains rimming the Valley of Trials were once simply a testing wilderness for young orcs and Darkspear trolls taking their first steps in service to the Horde. In recent days, however, dark rituals have taken hold of the northern caves. Imps and lesser fiends spill from the cavern mouth, stirring chaos and threatening recruits. Led by the shadowy warlock Yarrog Baneshadow, the Burning Blade cult has entrenched itself deep inside, turning what was once a routine training ground into an active battleground against demonic corruption. Before the demons took root, the caves attracted the attention of local overseers hoping to harvest raw materials for the settlement. Foreman Thazz'ril ventured deep inside on a mineral survey, only to be driven out in haste, leaving valuable equipment behind as the cultists made their presence known. Now, driving back Baneshadow's coven serves as the ultimate proving trial for aspiring warriors, rogues, and spellcasters before they are deemed ready to venture out into greater Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_burning-blade-coven-3e7c88e92d12acf1e464/1-0000.mp3", duration = 81.1102041, start = 0},
  },
}
P.transport["subzone:cleft-of-shadow"] = {
  hash = "351799",
  fullHash = "3046b4",
  text = "Cleft of Shadow. Tucked deep within the subterranean caverns beneath Orgrimmar, the Cleft of Shadow houses the city's practitioners of stealth, sorcery, and demonology. Far from the proud warrior ethos of Thrall's upper districts, it serves as a necessary haven for rogues, warlocks, and mages operating in the shadows of the Horde. While Thrall's new Horde champions honor, shamanism, and strength of arms, practical leadership demands a place for subtler arts. Carved into the damp stone caverns below the capital, the Cleft of Shadow hosts the Shadowswift Brotherhood of rogues, the Darkfire Enclave of warlocks, and the scholars of the Arcane Enclave. Kept away from the everyday bustle of the valley districts, this dark quarter allows practitioners of poison, fel energy, and arcane magic to ply their trades out of direct public view while remaining under the watchful eye of Orgrimmar's leadership. Beyond acting as a center for covert instruction and magical reagents, the Cleft of Shadow descends directly into Ragefire Chasm. This fiery network of volcanic caves honeycombs beneath Orgrimmar itself, posing an ongoing security threat that draws adventurous defenders and sinister cultists alike right to the cavern's edge.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_cleft-of-shadow-40ba2149d7dbe488ad52/1-0000.mp3", duration = 75.5722449, start = 0},
  },
}
P.transport["subzone:crag-of-the-everliving"] = {
  hash = "adb7a9",
  fullHash = "9387fe",
  text = "Crag of the Everliving. The Crag of the Everliving is a verdant cavern chamber nestled deep within the Wailing Caverns. Dominated by lush, corrupted flora and predatory plant creatures, it serves as the domain of the Fanglord Lord Pythas. Its towering upper reaches shelter the ancient entity after whom the crag is named. While much of the Wailing Caverns is carved of damp subterranean stone, the Crag of the Everliving bursts with unruly, twisted vegetation fueled by the Nightmare corrupting Naralex's slumber. Towering mossy platforms and winding paths are choked with Deviate Shamblers—living plant hulks prowling the undergrowth. Lord Pythas, one of Naralex's fallen disciples, watches over the crag's central reaches, having traded his noble druidic vows for the venomous rites of the Druids of the Fang. The chamber draws its name from Verdan the Everliving, a colossal, primordial plant elemental who resides in the crag's upper heights. Corrupted by the Emerald Nightmare that grips the cavern, Verdan now acts as a fearsome line of defense rather than a peaceful natural guardian. Beyond his towering form lurks Lord Serpentis, the self-proclaimed chief of the Fanglords, who oversees the sect's descent into serpentine madness.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crag-of-the-everliving-27ce3ec3d8a4023ea317/1-0000.mp3", duration = 76.7477551, start = 0},
  },
}
P.transport["subzone:crossroads"] = {
  hash = "fbb431",
  fullHash = "d7e94a",
  text = "Crossroads. The Crossroads is the beating heart of Horde travel through central Kalimdor, situated where the north-south Gold Road intersects the path from Ratchet to the Stonetalon Mountains. It serves as a bustling trading outpost, military staging area, and transit hub for travelers journeying between Durotar, Mulgore, and northern frontlines. True to its name, the Crossroads sits squarely at the crossing of the Gold Road and the east-west route cutting from the goblin port of Ratchet into the Stonetalon Mountains. Despite having modest lodgings, the outpost functions as a bustling regional hub. Wind rider masters, merchants, blacksmiths, and trainers maintain permanent setups beneath its watchtowers. For young warriors traveling out from Durotar or Mulgore, the settlement is often the first place they witness the vast, multi-front logistics binding the new Horde together. Maintaining order at the Crossroads is a relentless struggle. Local wildlife—including plains raptors bold enough to plunder payroll silver from the guard towers—poses a persistent nuisance, while harpies, quilboar, and centaur tribes continually pressure the perimeter. Beyond the threats native to the Barrens, the settlement's proximity to neutral Ratchet and the contested forests of Ashenvale makes it a prime target for encroaching Alliance scouting parties, leading to frequent skirmishes just outside its defensive barricades.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crossroads-cdafa3ccf418d02c6b77/1-0000.mp3", duration = 83.8008163, start = 0},
  },
}
P.transport["subzone:crusader-outpost"] = {
  hash = "585b99",
  fullHash = "a84283",
  text = "Crusader Outpost. Crusader Outpost is a fortified watchtower perched atop the rugged hills of eastern Tirisfal Glades. Manned by zealous members of the Scarlet Crusade, it guards the approaches leading toward their stronghold at the Scarlet Monastery. From this height, Crusaders observe travel along the road and stand ready to repel any Forsaken incursion. Built into the bluffs overlooking the eastern road, the Crusader Outpost serves as a primary early-warning station for the Scarlet Crusade. From their elevated tower, sentries watch over movement between Brill and the eastern reaches of Lordaeron, ensuring that wandering undead or scouting parties are spotted long before reaching the Monastery gates. The tower also grants the garrison tactical flanking capability against any force seeking to march up the valley toward their holy bastion. Under the command of Scarlet officers like Captain Vachon, the garrison stationed here maintains unwavering vigilance. They see the surrounding woods not as sovereign territory of the Forsaken, but as unhallowed soil stolen from humanity by monstrosities. For travelers loyal to the Undercity, the outpost represents an ever-present ambush point where crossbow bolts and cleansing steel await anyone straying too close to the bluffs.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crusader-outpost-6704ce8505fdeeb764bf/1-0000.mp3", duration = 74.7885714, start = 0},
  },
}
P.transport["subzone:crusader-s-outpost"] = {
  hash = "1721dd",
  fullHash = "9b7ca9",
  text = "Crusader's Outpost. Crusader's Outpost is a fortified scout tower manned by the Scarlet Crusade in western Tirisfal Glades. Situated adjacent to the Solliden Farmstead, it serves as the Crusade's westernmost position in all of Lordaeron. Its perilous distance from the main Scarlet bastions leaves its garrison isolated in the heart of hostile Forsaken territory. Perched inside the western Tirisfal hills just west of Deathknell, this stone tower represents the farthest reach of the Scarlet Crusade's power in Lordaeron. The garrison stationed here works in tandem with the surviving human laborers of the nearby Solliden Farmstead, attempting to hold back the encroaching undead. From the top of the tower, lookouts keep watch over the surrounding pumpkin fields and forest paths, vigilant against both roaming Scourge fiends and patrols from the Undercity. Holding the western frontier carries extreme risk. Cut off from their primary strongholds in the Scarlet Monastery and far to the east in Tyr's Hand, the crusaders at this outpost cannot expect swift reinforcements should an attack breach the palisade. Any siege by the Forsaken forces massing across Tirisfal means either holding the tower on their own or facing total annihilation before help can ever arrive.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_crusader-s-outpost-ce8d126c7b2377379bb0/1-0000.mp3", duration = 75.1020408, start = 0},
  },
}
P.transport["subzone:dawning-isles"] = {
  hash = "bcbfa8",
  fullHash = "8dc242",
  text = "Dawning Isles. The Dawning Isles are a cluster of low-lying islets situated within Lordamere Lake along the eastern edge of Silverpine Forest. Once idyllic retreats, they have succumbed to the blight of the Plague of Undeath and are overrun by aggressive murlocs. Before the Third War, the Dawning Isles were known as scenic keys resting on the calm, clear waters of Lordamere Lake. When the Plague of Undeath swept across Lordaeron, corruption seeped into the lake's shallows. The vegetation turned pallid and rotting, driving away idyllic peacefulness. Today, the Vile Fin murloc tribe dominates the muddy shores and tangled brush, aggressively defending their burgeoning colonies from anyone seeking to traverse the lake. Murlocs were not always the only danger on the isles. Bog beasts once prowled the blighted islets alongside them, but the bog beasts have since vanished. In their absence the Vile Fin population has swelled to the point that the murlocs now control the isles outright, turning what was once a quiet chain of keys into their stronghold on Lordamere Lake.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dawning-isles-4a2dffc26ab43d117847/1-0000.mp3", duration = 62.7983673, start = 0},
  },
}
P.transport["subzone:decrepit-ferry"] = {
  hash = "7557a1",
  fullHash = "3b2fb7",
  text = "Decrepit Ferry. The Decrepit Ferry is a ruined dock on the eastern shore of Silverpine Forest that once provided passage across Lordamere Lake to Fenris Isle. Following the fall of Lordaeron, the ferry was destroyed, its operator murdered, and the shoreline overrun by undead and vicious Rot Hide gnolls. Before the Third War, this dock bustled with daily traffic across Lordamere Lake. Local farmers brought fresh produce down to the water, selling their crops directly to the wealthy lord of Fenris Isle and his household. For a modest fee, the ferryman carried trade goods, messengers, and visiting nobles back and forth between the mainland and the keep. That peaceful commerce ended abruptly when the Scourge swept through the kingdom. The ferryman was brutally killed, the boats were smashed, and the pier fell into decay. Today, the docks are a hazard to any traveler passing along the lake shore. With the ferry out of commission, Fenris Isle sits isolated across the water, while the ruins themselves crawl with ghouls, skeletal warriors, and roving Rot Hide gnolls. What was once an orderly point of transit has become another festering pocket of danger in Silverpine.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_decrepit-ferry-3ba14afcfdc79b6d1f11/1-0000.mp3", duration = 71.1053061, start = 0},
  },
}
P.transport["subzone:drag"] = {
  hash = "1a62df",
  fullHash = "48f0c2",
  text = "Drag. The Drag is a bustling, shaded thoroughfare carved into the red rock of Orgrimmar, linking the Valley of Strength to the Valley of Honor and the Valley of Wisdom. Known throughout Durotar as the heart of the capital's commerce, its canyon walls are lined with crafters, traders, and artisans. It also conceals the cavernous descent into the notorious Cleft of Shadow. Tucked deep between the red canyon walls of Orgrimmar, the Drag serves as the commercial backbone of the Horde's capital. While the Valley of Strength focuses on military muster and administrative command, the Drag is where daily city life unfolds. Shaded under high cliffs and hides, the street is thick with the smells of tanning vats, bubbling alchemical cauldrons, and the clatter of tinkerers' gears. Craftsmen of almost every discipline gather here to practice their trades and teach aspiring adventurers, from leatherworking and tailoring to goblin-led engineering workshops like Nogg's Machine Shop. Beyond housing merchant storefronts and salvage houses, the Drag occupies an uneasy position within Orgrimmar's social geography. Nestled along its canyon face lies the guarded entrance to the subterranean Cleft of Shadow. This makes the Drag an inescapable crossroads where honest tradesmen, shaman on their way to the Valley of Wisdom, and secretive practitioners of dark arts brush shoulders beneath the dim, dusty overhangs of the canyon.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_drag-acae3418a4422f262574/1-0000.mp3", duration = 83.5918367, start = 0},
  },
}
P.transport["subzone:dry-hills"] = {
  hash = "4c27aa",
  fullHash = "477d2d",
  text = "Dry Hills. The Dry Hills form the rugged northwestern corner of the Barrens, nestled against the foothills of the Stonetalon Mountains. Contrary to their name, these uplands are noticeably greener than the arid plains below, though they are notoriously dangerous due to the aggressive Witchwing harpies roosting along their crags. Tucked away where the arid plains rise toward the Stonetalon Mountains, the Dry Hills are somewhat of a misnomer, possessing far more verdant brush and shrubbery than the sun-bleached savannas to the south. Yet this lush foothill region offers little safety for travelers. The bluffs are dominated by the Witchwing harpies, led by the matriarch Serena Bloodfeather. From these heights, their raiding parties sweep down to prey on supply caravans using the northern stretch of the Gold Road, leaving abandoned orcish fortifications and derelict siege engines rotting in the brush. Because the Witchwing harpies routinely strike out of the hills to bleed trade routes and harass nearby settlements, the Horde maintains a standing bounty on their feathers. Adventurers venturing deep into the rocky ravines will encounter not only heavily defended harpy nests and roosts, but also prowling Hecklefang hyenas and fierce Sunscale raptors that hunt throughout the highlands.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dry-hills-31a70c2bf242b64e303d/1-0000.mp3", duration = 73.0122449, start = 0},
  },
}
P.transport["subzone:drygulch-ravine"] = {
  hash = "1821a1",
  fullHash = "ec6e2f",
  text = "Drygulch Ravine. Drygulch Ravine is a rugged, hidden gorge tucked into the rocky bluffs of eastern Durotar. Accessible only through an obscure cave passage from Razorwind Canyon or a perilous drop from above, this craggy trench is overrun by nesting Dustwind harpies who menace nearby supply caravans. Carved deep into the crags east of Orgrimmar, Drygulch Ravine is almost entirely cut off from casual travel. Its only ground-level access is a cramped natural tunnel connected to Razorwind Canyon. Fed by a modest river, this sheltered depression once saw peaceful orc habitation, but wild beasts and roosting Dustwind harpies have turned it into a lawless pocket of Durotar. The winged scavengers use the steep cliff faces to nest their broods and stockpile stolen goods taken from Horde supply trains passing along the regional trails. Life in Drygulch Ravine has long been precarious. Not long after the Third War, escaped thunder lizards from Thunder Ridge threatened the area, prompting warnings to Warchief Thrall in Orgrimmar. Today, the harpies pose the immediate danger. Their matriarchs fiercely defend clutches of eggs tucked along the high ledges, and Horde scouts frequently dispatch young warriors to cull the flock, recover plundered trade crates, and break the harpies' grip on the ravine.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_drygulch-ravine-9fb018ba0d0fa07ba7a6/1-0000.mp3", duration = 81.1102041, start = 0},
  },
}
P.transport["subzone:dustwind-cave"] = {
  hash = "f4b0c3",
  fullHash = "46acf4",
  text = "Dustwind Cave. Dustwind Cave is a secluded hollow perched atop the cliffs of Razorwind Canyon, just northeast of Razor Hill. It serves as an active training ground and covert sanctuary for initiates of the nefarious Burning Blade cult operating within Durotar. Overlooking Razorwind Canyon, Dustwind Cave is one of the closest and most perilous threats to Razor Hill. While many assume demonic cultists gather only in deep subterranean depths, here the Burning Blade trains fresh recruits right under the noses of the Horde authorities. Shadowy cultists tutor initiates in forbidden dark magics and demonology, preparing them to undermine the young orcish realm from within Durotar's own borders. Those who trespass into the cave risk exposure to the cultists' dangerous corruptions. Practitioners inside channel volatile dark arts such as felblood afflictions, demonstrating how deeply the Burning Blade clings to the demonic legacy Thrall fought so hard to banish. Eliminating the cabal here is vital for maintaining the precarious peace of Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_dustwind-cave-ab4a42c2438c7d876ab3/1-0000.mp3", duration = 64.5485714, start = 0},
  },
}
P.transport["subzone:echo-isles"] = {
  hash = "e70f1a",
  fullHash = "ad21e5",
  text = "Echo Isles. The Echo Isles are a cluster of tropical islands lying just off the southeastern coast of Durotar. Originally settled by the Darkspear trolls after fleeing their ancestral islands, the archipelago is currently lost to the rogue witch doctor Zalazane, who drove his people into exile with dark magic and enslaved minions. Following their flight across the Great Sea alongside Thrall, the Darkspear tribe claimed the Echo Isles as their new home. Their peace was repeatedly shattered: first by the naval forces of Grand Admiral Daelin Proudmoore during Kul Tiras' invasion of Durotar, and later from within. Shortly after the trolls drove back Proudmoore's fleet, one of their own witch doctors, Zalazane, seized dark arts to enslave the minds of his kin. Chieftain Vol'jin and the free Darkspears were forced to abandon the islands once more, seeking temporary refuge across the narrow strait at Sen'jin Village. Today, the tropical cluster is overrun by aggressive predators, tainted wildlife, and the thralls of Zalazane. Using malevolent hexes, voodoo fetishes, and ju-ju heaps placed throughout the islands, the traitorous witch doctor bends beasts and captive trolls to his will. From their encampment at Darkspear Strand, Vol'jin's scouts and warriors mount frequent sorties into the islands, determined to recover the remains of their fallen and strike down the mad mystic who stole their home.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_echo-isles-1345992b6c7ca00e4744/1-0000.mp3", duration = 84.7934694, start = 0},
  },
}
P.transport["subzone:elder-rise"] = {
  hash = "c25d39",
  fullHash = "5d3a20",
  text = "Elder Rise. Elder Rise sits directly east of Thunder Bluff's central plateau, reachable across long suspension bridges from both the High and Middle Rises. It serves as the spiritual heart of the tauren capital, hosting the Cenarion Circle, tauren druids and priests, and the governing Council of Elders. Connected to the main mesas by swaying rope bridges, Elder Rise is dedicated to quiet reflection, sacred wisdom, and civic governance. Tauren druids and priests gather here to teach acolytes the ways of nature and spiritual devotion. High atop this mesa resides Arch Druid Hamuul Runetotem, the revered leader who brought druidism back to the tauren people and forged close ties with the Cenarion Circle. Alongside these wild sanctuaries stands the Hall of Elders, where tribal leaders convene to deliberate on matters facing their fledgling capital. Despite its role as a peaceful sanctuary, political tension lingers over the rise. Magatha Grimtotem, elder matriarch of the secretive and haughty Grimtotem tribe, maintains her residence in a hut positioned between the two bridges. While Cairne Bloodhoof extends hospitality and formal council seats to all tauren lineages, her watchful presence serves as a constant reminder that not every tribe embraces the Bloodhoof's pacifist ideals or unquestioning alliance with the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_elder-rise-cbdd625ae988254f5c2e/1-0000.mp3", duration = 80.9534694, start = 0},
  },
}
P.transport["subzone:faol-s-rest"] = {
  hash = "ea0320",
  fullHash = "d5a0a5",
  text = "Faol's Rest. Faol's Rest is a quiet, neglected gravesite situated in eastern Tirisfal Glades, just southwest of the Scarlet Monastery. It was erected as the tomb of Archbishop Alonsus Faol, the revered spiritual patriarch who founded the Knights of the Silver Hand. Today, untended beneath the blighted canopy, it serves as a release graveyard for those who perish near the monastery. Before the Third War devastated Lordaeron, this secluded hollow was a place of solemn pilgrimage. It holds the stone tomb of Archbishop Alonsus Faol, who led the Church of the Holy Light through the dark days of the Second War and instituted the order of paladins to protect humanity. Faol passed away peacefully prior to the arrival of the Scourge, spared the mortal agony of seeing his kingdom fall. In those brighter years, mourners regularly journeyed up the road from Capital City to leave offerings and pay respects to the beloved patriarch. When the Plague of Undeath swept across Lordaeron, Tirisfal withered, and the pilgrims vanished. Today, the monument sits abandoned and cracked in the shadows beneath the Scarlet Monastery's high bluffs. The wild brush has reclaimed the pathways, and the tomb itself lies still amid the damp mist. For adventurers striving against the zealots of the Scarlet Crusade or the lingering terrors of Tirisfal, this forgotten resting place now serves primarily as a quiet threshold where fallen spirits briefly regroup before returning to the fray.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_faol-s-rest-5a2034f1c1c522758598/1-0000.mp3", duration = 88.7640816, start = 0},
  },
}
P.transport["subzone:field-of-giants"] = {
  hash = "6539dd",
  fullHash = "13a801",
  text = "Field of Giants. The Field of Giants is an expansive plain covering the southern Barrens between Camp Taurajo and the marshes of Dustwallow. Named for the towering kodo, thunder lizards, and massive beasts that graze its arid scrub, the region has recently grown far more perilous due to an encroaching silithid infestation. Stretching along the southern span of the Gold Road, the Field of Giants is remote, rugged, and lightly defended compared to the Barrens to the north. While the road's wooden watchtowers stand largely abandoned, the land itself thrums with life. Tremendous herds of Kalimdor's megafauna wander the vast flats, drawing hunters and naturalists alike. However, safety is elusive here: dwarven excavators from Bael Modan dig aggressively to the south, and a far more sinister menace has begun burrowing beneath the earth. In recent times, insectoid silithid hives have erupted from the ground across the Field of Giants, marking the northernmost known sighting of these ravenous creatures in Kalimdor. These strange mounds and aggressive swarms have alarmed the Horde. Scouts such as the troll Korran from the Crossroads and tauren warriors like Ruga Ragetotem at Camp Taurajo urge adventurers to probe the hives, seeking to uncover what draws these subterranean horrors so far from the deep deserts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_field-of-giants-919337cd3c6c05176939/1-0000.mp3", duration = 82.5469388, start = 0},
  },
}
P.transport["subzone:forgotten-pools"] = {
  hash = "62332d",
  fullHash = "07c5c3",
  text = "Forgotten Pools. The Forgotten Pools is the northernmost of the verdant oases scattered across the arid Barrens, located just northwest of the Crossroads. Fed by subterranean springs, this vibrant pocket of lush flora and waters is bitterly contested between indigenous wildlife, wandering Kolkar centaur, and the Horde. Situated off the western road leading out of the Crossroads, the Forgotten Pools offers a stark contrast to the parched savannas that surround it. Thick reeds, palm trees, and unusual flora like Laden Mushrooms cluster around its freshwater shore, drawing plainstriders, snapjaw turtles, and zhevras from miles around. However, the oasis is far from peaceful. Kolkar centaur maintain a constant encampment along the banks, jealously guarding the water supply against travelers and bringing them into direct conflict with Horde travelers from the Crossroads. Beyond its strategic value as a watering hole, the Forgotten Pools harbors peculiar ecological traits. It is one of the rare surface waters in the region where the enigmatic Deviate Fish thrive, hinting at deeper subterranean ties to the strange transformative energies altering the Barrens' water table. Horde naturalists and scouts keep a close eye on the waters and the unique fungal growths along the banks, wary of what might be seeping into the soil.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_forgotten-pools-df282ddeaa2200cd65d2/1-0000.mp3", duration = 78.5502041, start = 0},
  },
}
P.transport["subzone:fray-island"] = {
  hash = "a45c2f",
  fullHash = "101d4f",
  text = "Fray Island. Fray Island is a windswept, rocky islet lying just off the Merchant Coast of the Barrens. Home to a rough-and-tumble training ring, it is famous as a neutral haven where warriors from across Azeroth come to test their mettle. Situated off the eastern bluffs of the Barrens, Fray Island is far removed from the watchful eyes of both Orgrimmar and Theramore. The island serves as a training place for warriors of all races and creeds. At its heart sits a fighting arena overseen by Klannoc Macleod, where seasoned fighters and raw recruits gather to compete in brutal brawls. Despite the hostility of the surrounding waters, the island's central ring adheres to a simple code of martial combat. Warriors journey here on the instructions of their trainers to take part in 'The Affray'—a grueling gauntlet against waves of challengers culminating in a bout against the champion Big Will. Here, allegiance to Horde or Alliance is set aside in favor of raw strength and martial discipline.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_fray-island-87c281f36a6c90eb2a50/1-0000.mp3", duration = 58.7232653, start = 0},
  },
}
P.transport["subzone:gallows-end-tavern"] = {
  hash = "40c938",
  fullHash = "3fae5b",
  text = "Gallows' End Tavern. Gallows' End Tavern is the principal inn of Brill and the heart of Forsaken hospitality in Tirisfal Glades. Beyond offering shelter and spirits to weary travelers, it serves as an essential hub for class mentors, trade instructors, and covert interrogations. Standing prominently along the road in Brill, Gallows' End Tavern serves as the primary gathering place for newly awakened Forsaken leaving Deathknell and journeying south toward the Undercity. Despite their undead condition, Forsaken still frequent its halls for fellowship, trade, and refuge. The inn houses various class instructors—guiding young warriors, priests, mages, rogues, and warlocks—as well as vendors and medical practitioners. Beneath the creaking floorboards and tavern laughter lies a far grimmer purpose. Down in the cellars, the Forsaken keep prisoners of war bound and guarded away from public view. Among them are a captured Scarlet Zealot and a Dwarven Mountaineer, held beneath the tavern for interrogation and experimentation as the Forsaken fight to secure their borders against both zealous crusaders and Alliance scouts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gallows-end-tavern-b3c8c0d2ecbbd8ff3469/1-0000.mp3", duration = 68.2318367, start = 0},
  },
}
P.transport["subzone:garren-s-haunt"] = {
  hash = "bf3c2a",
  fullHash = "b4c037",
  text = "Garren's Haunt. Garren's Haunt is an abandoned farmstead nestled in northern Tirisfal Glades. Once a prosperous human homestead, the farm fell to ruin when the Scourge wiped out the Garren family, leaving the overgrown grounds overrun by feral Rot Hide gnolls. Before the Third War, this farmstead supported a family and produced bountiful harvests under the Kingdom of Lordaeron. When the Plague of Undeath swept across the countryside, the Scourge descended upon the farm and slaughtered Garren and his kin. Today, the fields lie gray and withered, the farmhouse and barn decaying under the perpetual gloom of Tirisfal. Rather than standard Scourge patrols, Garren's Haunt has been claimed by the Rot Hide gnolls—a pack of undead-tainted scavengers led by the vicious Maggot Eye. These scavengers aggressively defend their reclaimed territory, picking clean whatever remains of the farm and savaging any travelers or Forsaken patrols passing along northern Tirisfal.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_garren-s-haunt-59f3b2a74c28ec7e364f/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["subzone:gold-road"] = {
  hash = "c08f50",
  fullHash = "99f2ff",
  text = "Gold Road. The Gold Road is the primary north-south artery cutting through the arid expanse of the Barrens. Stretching from the Mor'shan Rampart on the border of Ashenvale down past the Crossroads toward the southern reaches, it serves as the vital transit line for the young Horde. The Gold Road is a long, sun-baked dirt highway that carves its way through the center of the Barrens. To the north, it begins near the fortified Mor'shan Rampart and Mor'shan Base Camp, which guard against night elf incursions from Ashenvale. Traveling south, it connects with the eastern roadway leading to Durotar before intersecting the bustling trading settlement of the Crossroads. Continuing southward past the lush waters of the local oases and the foothills near the Wailing Caverns, the northern span of the highway reaches a dried-up riverbed, where travelers cross into the more hazardous southern portion of the savanna. Despite being the lifeblood of Horde trade and military movement between Kalimdor's central territories, the Gold Road is perilous. Marauding quilboar tribes, centaur warbands, and prowling plainstriders and lions constantly threaten supply caravans and solitary messengers. The Horde expends considerable resources deploying scouts and warriors along its length, yet travelers are urged to remain armed and alert whenever leaving the safety of the major outposts.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_gold-road-6adeb0e3047739a42afa/1-0000.mp3", duration = 80.0653061, start = 0},
  },
}
P.transport["subzone:grol-dom-farm"] = {
  hash = "113550",
  fullHash = "fc7131",
  text = "Grol'dom Farm. Grol'dom Farm is a modest orcish homestead situated in the northern Barrens along the road between Durotar and the Crossroads. Inhabited by Kranal Fiss and his family, the farm raises swine in the arid plains despite constant harassment from aggressive local quillboars. Established following the settlement of Durotar, Grol'dom Farm represents the Horde's early efforts to farm the dry expanse of the Barrens. Tended by the orc Kranal Fiss and his children, the small homestead primarily raises pigs while braving the harsh wildlife and aggressive Razormane quillboar raiders that prowl the nearby ridges. It is a lonely, rugged outpost that supplies vital sustenance to the emerging orcish nation. Beyond its mundane function as a pig farm, the homestead holds quiet importance for Horde initiates on the spiritual path. Kranal Fiss possesses deep knowledge of elemental rites and plays a key role in guiding young shaman through their trials. Seekers traveling west from Orgrimmar are regularly directed to this humble farm to learn the secrets necessary to commune with the primal spirits of fire.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grol-dom-farm-81fc2e902eb49bcee170/1-0000.mp3", duration = 65.7502041, start = 0},
  },
}
P.transport["subzone:grommash-hold"] = {
  hash = "5773b2",
  fullHash = "861a29",
  text = "Grommash Hold. Grommash Hold is the fortified seat of Warchief Thrall, nestled high in the red cliffs of the Valley of Wisdom in Orgrimmar. Named in honor of Grommash Hellscream's sacrifice, the fortress serves as the command center and political heart of the new Horde. Perched within the tranquil Valley of Wisdom, Grommash Hold serves as the royal court and strategic sanctum of the Horde. Built into the towering canyon walls, its thick stone interior remains notably dim and chilly—a deliberate choice by Warchief Thrall to keep emissaries, petitioners, and warlords sharp and sober during audiences. Here, Thrall deliberates on the defense of Kalimdor, guided by veteran counselors like Eitrigg and visited by racial chieftains such as Vol'jin. Just outside the stronghold rests the shattered armor and horned skull of the pit lord Mannoroth, mounted upon the trunk of an ancient tree. Placed there to honor Grom Hellscream, who traded his life to slay the demon in Ashenvale, the memorial stands as both a proud symbol of the orcs' liberation from the demonic blood curse and a permanent, solemn warning against falling into reckless savagery again.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_grommash-hold-0dcc12f06291a3e6a237/1-0000.mp3", duration = 70.8702041, start = 0},
  },
}
P.transport["subzone:hall-of-legends"] = {
  hash = "1a8a9d",
  fullHash = "3087ed",
  text = "Hall of Legends. The Hall of Legends is the elite military sanctuary and officer barracks of the Horde, nestled within Orgrimmar's Valley of Strength. Behind its warded threshold, champions of the Horde gather around battle plans and arm themselves with premier weapons taken from conflicts across Azeroth and beyond. Located off the bustling avenues of the Valley of Strength, the Hall of Legends serves as the private redoubt for proven officers of the Horde. Beyond its guarded entrance, strategists and delegates from across the factions—including Chieftain Earthbind of Thunder Bluff, Blood Guard Hini'wana of the Darkspear, and Advisor Willington of the Undercity—confer over maps of contested lands and the military standing of both factions. Here, only warriors who have tested their mettle and achieved the rank of Stone Guard or higher are permitted entry to claim the spoils and armaments befitting their status. More than just an officer lounge, the hall houses armories containing battle-tested wargear from across Azeroth and the orcs' shattered homeworld of Draenor. Many of these weapons were claimed as spoils from the ongoing clashes against the Alliance and other adversaries. For those climbing the martial ranks, it represents the physical manifestation of Horde honor, martial prowess, and hard-won victory.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hall-of-legends-3f4a99f5d429460d9787/1-0000.mp3", duration = 75.2065306, start = 0},
  },
}
P.transport["subzone:hidden-path"] = {
  hash = "cf7e7a",
  fullHash = "786c14",
  text = "Hidden Path. The Hidden Path is a secluded mountain trail winding through the crags above the Valley of Trials in Durotar. It serves as a rite of passage for aspiring shaman seeking the sacred Spirit Rock, while offering an overlooked vantage overlooking the rugged borders of the Barrens. Carved into the red peaks bordering the Valley of Trials, the Hidden Path is intentionally difficult to spot from the canyon floor. Young shaman are directed here by their mentors to prove their awareness and discipline before communing with the spirits at Spirit Rock. Along the trail's highest reaches, travelers are treated to expansive panoramic views stretching westward toward the rolling savannas of the Barrens. Beyond its spiritual importance, the path cuts a precarious breach through the natural fortifications enclosing the valley. A low pass along the route provides a direct back door toward Ratchet and the road to Orgrimmar. Because it circumvents the standard canyon checkpoints, vigilant defenders fear that bold Alliance infiltrators could exploit this quiet trail to slip directly into the Horde's primary proving grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hidden-path-13552d434e8b76d0bc50/1-0000.mp3", duration = 62.484898, start = 0},
  },
}
P.transport["subzone:hunter-rise"] = {
  hash = "82a031",
  fullHash = "2dff60",
  text = "Hunter Rise. Hunter Rise is one of the elevated mesas making up the city of Thunder Bluff, situated just south of the central bluff. It serves as the primary training and gathering ground for the tauren's warriors, hunters, trackers, and skinners. Across its windswept platforms, young braves hone their martial skills and prepare for combat. Connected to the neighboring bluffs by swaying rope bridges, Hunter Rise is dedicated to the martial traditions of the tauren. It is anchored by the Hunter's Hall, where experienced marksmen, trackers, and warriors pass down their discipline to younger generations. Surrounding the lodge are practice grounds outfitted with training dummies, weapon racks, and skinning posts, making it a bustling center for those who live by spear, bow, and hide. Beyond hunting wild game across the plains of Mulgore, the inhabitants of Hunter Rise help ensure the defense of Thunder Bluff and the wider Horde. Battlemasters stationed along the rise recruit seasoned fighters to answer the call of skirmishes against Alliance incursions across contested battlegrounds. It remains an essential rallying point for anyone sworn to protect the herd.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_hunter-rise-4d24e737ae6dd4215c8a/1-0000.mp3", duration = 65.515102, start = 0},
  },
}
P.transport["subzone:jaggedswine-farm"] = {
  hash = "809fa5",
  fullHash = "2d4e2d",
  text = "Jaggedswine Farm. Jaggedswine Farm is a modest livestock steading situated in northern Durotar, just south of the main entrance to Orgrimmar. Comprising a timber storage shed, a sprawling pen, and a muddy watering hole, it serves as a critical food source raising hardy swine for the nearby Horde capital. Carved out of Durotar's unforgiving, sunbaked earth, Jaggedswine Farm represents the harsh reality of sustaining an urban stronghold like Orgrimmar. The red soil of the region yields sparse agriculture, making robust livestock essential to feeding thousands of orcish warriors and laborers. The farm centers on a timber storehouse, a wide wooden pen, and a natural watering pond where swine are herded, bred, and butchered to keep the Horde's granaries stocked. Though quiet and often appearing half-tended under the dry heat, the farm is a regular stomping ground for local swineherds and patrolling Orgrimmar Grunts. Wild and mature swine roam both inside and outside the enclosures, occasionally testing the patience of nearby guards. Sitting right on the threshold of the capital's valley approach, the plot remains an unassuming yet indispensable outpost in the daily logistics of Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_jaggedswine-farm-7c2041399b58d76cf8f7/1-0000.mp3", duration = 74.24, start = 0},
  },
}
P.transport["subzone:kodo-rock"] = {
  hash = "6ab2c5",
  fullHash = "35194b",
  text = "Kodo Rock. Kodo Rock is a natural stone monument located in the plains of Red Cloud Mesa, between Camp Narache and Brambleblade Ravine. Standing quietly amid the grasses of Mulgore, it serves as an early pilgrimage site for young tauren shamans learning to commune with the spirits of the earth. Because of its modest silhouette against the rolling landscape, travelers must keep a keen eye out to spot it. Situated roughly halfway along the path connecting Camp Narache to the hostile quillboar territory of Brambleblade Ravine, Kodo Rock is marked by a patch of worn earth at its base. While it lacks the sheer grandeur of the towering bluffs surrounding Red Cloud Mesa, its distinct profile resembles the revered kodo beasts that wander the grasslands. For wandering tribesfolk, it acts as a quiet natural beacon in the windswept plains of Mulgore. To the Shu'halo, natural formations often carry spiritual weight. Kodo Rock holds special reverence for young tauren shamans beginning their spiritual walk. Novices are directed here on early rites of passage, using the solitary stone monument as a sacred grounds to commune with elemental forces and honor the natural world before venturing into more perilous reaches of the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_kodo-rock-4228eece132a2a9020fc/1-0000.mp3", duration = 75.284898, start = 0},
  },
}
P.transport["subzone:magic-quarter"] = {
  hash = "04a440",
  fullHash = "c12adf",
  text = "Magic Quarter. The Magic Quarter is the northeastern district of the Undercity, serving as the center for Forsaken arcane study and dark spellcraft. Dominated by an ominous Temple of the Damned, the quarter houses practitioners of both the arcane and fel arts. Occupying the northeastern quadrant of the subterranean city, the Magic Quarter is where the Forsaken preserve their arcane heritage and delve into darker methodologies. The centerpiece of the district is a looming Temple of the Damned, an architectural relic of Scourge design that has been repurposed by the free-willed undead. Beneath its vaulted, shadowy ceilings, mages practice subtle manipulations of magical energies alongside warlocks communing with demonic entities, making the quarter the nexus of intellectual power and occult research in Lordaeron. Beyond the study of raw evocation and summoning, the Magic Quarter functions as an essential civic hub for spellcasters. Portal trainers maintain transport links across Horde territories, while master tailors work with magically infused fabrics to craft robes and shrouds. Unlike Dalaran's strict segregation between academic wizardry and forbidden magic, the Forsaken blend arcane curiosity and fel power openly within these halls to secure their place against their many enemies.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_magic-quarter-565b509f2f2cc2fb1dce/1-0000.mp3", duration = 75.5722449, start = 0},
  },
}
P.transport["subzone:night-web-s-hollow"] = {
  hash = "5cc039",
  fullHash = "ebc28d",
  text = "Night Web's Hollow. Night Web's Hollow is a sunken vale and abandoned gold mine located just northwest of Deathknell in Tirisfal Glades. Heavily overrun with arachnids, it serves as a testing ground for freshly awakened Forsaken sent to cull the vermin and prove their combat readiness. Tucked away in the northern hills of Deathknell, Night Web's Hollow was once an ordinary human gold mine before the plague swept through Lordaeron. In the aftermath of the kingdom's fall, the shafts were entirely abandoned to nature. Today, thick strands of webbing shroud the rock walls and suffocating shadows conceal a thriving colony of aggressive night web spiders. Freshly raised Forsaken are routinely dispatched into the hollow and its subterranean tunnels to cull the young and adult spiders so the Forsaken can regain access to the mine's gold.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_night-web-s-hollow-8221750426a47043f92e/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["subzone:nightmare-vale"] = {
  hash = "ec7664",
  fullHash = "c83b22",
  text = "Nightmare Vale. Nightmare Vale is a shadowed hollow nestled in southwestern Tirisfal Glades, just west of the Crusader's Outpost. Once a lush forest haven, its trees have withered under the blight, and vicious predators now roam among the twisted trunks. Before the Third War, this valley was a verdant part of the Tirisfal countryside, filled with songbirds and standard woodland game. In the wake of the Scourge's plague, the vegetation has blackened and rotted away. Ravenous darkhounds and massive vampire bats have devoured the native wildlife, turning the hollow into a grim haven for scavengers and beasts of prey. Lurking in the shadows of Nightmare Vale is Ressan the Needler, an unusually large, pale vampire bat notorious among local travelers. Wedged uncomfortably between the haunted wilderness and the zealous sentries at the nearby Crusader's Outpost, the vale is an unforgiving expanse where unwary adventurers quickly become prey.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_nightmare-vale-b91f55bf486fcfb0d464/1-0000.mp3", duration = 57.4432653, start = 0},
  },
}
P.transport["subzone:north-coast"] = {
  hash = "6d0ae2",
  fullHash = "947b9e",
  text = "North Coast. The North Coast is a bleak, fog-shrouded stretch of shoreline marking the northern edge of Tirisfal Glades along the Great Sea. Tainted by the fall of Lordaeron, the cold beaches are littered with rotting marine life and aggressively defended by tribes of hostile murlocs. Before the Third War, these northern waters and stony beaches were part of the peaceful northern boundary of Lordaeron. When the Plague of Undeath swept across the continent, its corrupting blight seeped down the bluffs and poisoned the coast. The waters turned chill and murky, washing up the carcasses of giant sea creatures that now rot upon the sand amid the perennial coastal fog. With the human kingdom shattered and the Forsaken focusing their attention around Brill and the Capital City, coastal murlocs claimed the desolate sands. The local Vile Fin tribe maintains huts along the surf, utilizing nearby shallows as spawning grounds. Swarms of ravenous murlocs, including notable figures like Deeb and numerous growing tadpoles, violently guard the tideline against any surface-dwellers.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-coast-6b1d3739a173ab3cc774/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["subzone:north-tide-s-hollow"] = {
  hash = "5a3695",
  fullHash = "f3edca",
  text = "North Tide's Hollow. North Tide's Hollow is a rugged wilderness pocket in Silverpine Forest located just north of the Sepulcher. Haunted by feral Moonrage worgen loyal to the rogue Archmage Arugal, the clearing serves as a base of operations for the beasts stalking the coastal woods. Tucked away in the dense timber north of the Forsaken settlement of the Sepulcher, North Tide's Hollow is dominated by the savage Moonrage pack. These feral worgen, brought into Lordaeron through the reckless sorcery of Archmage Arugal, have established crude encampments throughout the hollow. Built with only the barest necessities required by the hardy beasts, these rough shelters provide a forward staging ground dangerously close to Forsaken travel routes. Unlike ordinary wilderness predators, the worgen of North Tide's Hollow answer to the sinister will emanating from Shadowfang Keep. Their proximity to both the western shoreline and the main road through Silverpine makes them a constant menace to Forsaken couriers and patrols attempting to secure the region.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-tide-s-hollow-fd517e41fd870a72d92c/1-0000.mp3", duration = 60.4734694, start = 0},
  },
}
P.transport["subzone:north-tide-s-run"] = {
  hash = "7fe903",
  fullHash = "625f76",
  text = "North Tide's Run. North Tide's Run is the windswept northwestern shoreline of Silverpine Forest, skirting the edge of the Great Sea. Marked by a lonely campfire and a half-sunken shipwreck, this stretch of sand is known as a secluded trial ground for traveling druids seeking harmony with the waters. Stretching along the northwest edge of Silverpine Forest, North Tide's Run consists of cold sand, pounding surf, and a strip of the Great Sea. Its most unmistakable landmark is a partially submerged shipwreck tilted precariously in the shallows near the beach. Aside from the wreckage, the only sign of habitation is a humble campfire tended by Wallace the Blind, who keeps a quiet vigil beside the lapping tide. Despite its bleak atmosphere, North Tide's Run holds sacred importance for Horde initiates walking the path of Cenarius. Young tauren druids are directed here on pilgrimage to recover underwater relics lost to the waves, testing their lung capacity and endurance to earn the blessing of the aquatic form.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_north-tide-s-run-93bcd6978b5ba360c393/1-0000.mp3", duration = 62.7983673, start = 0},
  },
}
P.transport["subzone:razor-hill-watchtower"] = {
  hash = "73e7a1",
  fullHash = "c1980e",
  text = "Razor Hill Watchtower. Perched on the red stone bluffs overlooking Razor Hill, this sturdy outpost serves as an early warning post for the heart of Durotar. Furl Scornbrow keeps a vigilant eye across the dusty plains and toward the coast, safeguarding the settlement below from encroaching threats. Constructed from thick timber and iron framing, the Razor Hill Watchtower guards the settlement of Razor Hill and the surrounding canyons. Durotar faces relentless threats from Kul Tiras marines along the eastern shore, quillboar raiders prowling the scrublands, and Burning Blade cultists lurking in nearby crags. From this elevated vantage point atop the ridgeline, the lookout can spot approaching warbands, smoke signals, and incursions long before they reach the settlement gates.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_razor-hill-watchtower-874e3c3889fc70262c39/1-0000.mp3", duration = 46.0016327, start = 0},
  },
}
P.transport["subzone:sewers"] = {
  hash = "dd7916",
  fullHash = "81da28",
  text = "Sewers. The Sewers are a sprawling subterranean drainage network that provides a secondary entrance directly into the Undercity. Cutting beneath the hills west of the ruined palace of Lordaeron, this conduit allows bat handlers and stealthy travelers to bypass the precarious elevators leading down from the throne room. Before the plague wiped out Lordaeron, these stone culverts served as the mundane sewer lines draining the royal capital. In the hands of Sylvanas Windrunner's Forsaken, however, the runoff tunnels have been integrated into the Undercity's outer defenses. Emerging west of the surface ruins near a contested Scarlet Watchtower in Tirisfal Glades, the passage provides a level, direct slope inside. Forsaken bat handlers use this cavernous conduit to fly riders swiftly into the subterranean rings, avoiding the sluggish cage lifts entirely. Because it circumvents the heavily fortified surface courtyards, it remains a dangerous vulnerability that hostile infiltrators constantly seek to exploit.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_sewers-2325bca66febc3c15489/1-0000.mp3", duration = 59.5069388, start = 0},
  },
}
P.transport["subzone:the-den"] = {
  hash = "0e9c7b",
  fullHash = "c98189",
  text = "The Den. The Den is the sheltered cave at the heart of the Valley of Trials in southwestern Durotar. Serving as the primary base of operations for young orc and troll adventurers, it provides martial and magical training before they set out into the wider world. Tucked into the red canyon walls of the Valley of Trials, the Den serves as an austere proving ground. Within its carved, shadowy interior, novice fighters, spellcasters, and hunters report to veterans like Gornek and Zureetha Fargaze. It is here that fledglings receive their foundational combat instruction, supplies, and initial rites of passage, hardening them for the harsh realities of Durotar and the greater struggles facing the new Horde. Beyond housing class trainers and provisions, the Den functions as an active field redoubt. Between dispatching new recruits to cull the local beasts and aggressive quillboars, the overseers maintain a strict, vigilant watch over the valley.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_the-den-18ed732acf2db843ee7b/1-0000.mp3", duration = 57.1297959, start = 0},
  },
}
P.transport["subzone:thunder-ridge"] = {
  hash = "25df62",
  fullHash = "0c26be",
  text = "Thunder Ridge. Thunder Ridge is a rugged canyon in western Durotar, situated just southwest of Orgrimmar along the banks of the Southfury River. Once a lush grove of ancient trees inhabited by herds of thunder lizards, the canyon has suffered severe deforestation from human lumber operations and dark sorcery. Today, the agitated beasts and lingering cultists pose an ongoing threat to nearby settlements. Not long ago, Thunder Ridge was a rare green haven in arid Durotar, sustained by ancient trees. Its tranquil balance shattered shortly after the Third War when human interlopers from Kul Tiras began felling its timber, driving the native thunder lizards into a frenzy. Later, fel sorcery wielded by the Burning Blade finished the destruction, stripping the canopy and leaving behind a barren, exposed gorge where angry lightning-spewing beasts now roam unrestrained.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_thunder-ridge-22553410c0cbe642edc0/1-0000.mp3", duration = 53.8906122, start = 0},
  },
}
P.transport["subzone:tiragarde-keep"] = {
  hash = "99f7e6",
  fullHash = "970fe2",
  text = "Tiragarde Keep. Tiragarde Keep is a fortified human stronghold situated along Durotar's Scuttle Coast, south of Razor Hill. Originally built during Grand Admiral Daelin Proudmoore's invasion, the ruined citadel remains garrisoned by hostile Kul Tiran marines under Lieutenant Benedict. It serves as a defiant, permanent thorn in the Horde's side right on their home territory. Erected during Grand Admiral Daelin Proudmoore's campaign to eradicate Thrall's newly founded realm, Tiragarde Keep provided the Kul Tiran fleet an entrenched beachhead on the red shores of Durotar. Although the Horde eventually broke the siege and killed Proudmoore at Theramore Isle, the keep was never fully abandoned. Resupply forces under Lieutenant Benedict reclaimed the shattered stone walls, following the late Admiral's standing orders to wage an unyielding war against the orcs, entirely refusing the peace forged by Lady Jaina Proudmoore. Today, the keep's gleaming white battlements stand in harsh contrast against Durotar's crimson cliffs. Well-trained Kul Tiras sailors and marines patrol the ramparts and launch raids targeting supply lines near Razor Hill. For the Horde, Tiragarde Keep is an ongoing security crisis and a live proving ground. Orc and troll commanders constantly task young warriors with assaulting the fortress and cutting down Benedict's soldiers, seeking to contain the garrison before the humans can mount a deeper inland offensive.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tiragarde-keep-9be23ad3a8c4fa492a49/1-0000.mp3", duration = 85.7338776, start = 0},
  },
}
P.transport["subzone:tor-kren-farm"] = {
  hash = "95c1bf",
  fullHash = "e8197a",
  text = "Tor'kren Farm. Tor'kren Farm is a quiet, struggling swine farm in northwestern Durotar, near Thunder Ridge and the Southfury River. Misha Tor'kren tends the homestead while anxiously awaiting news of her son Kron, who has not returned from a hunting trip. Carving out a living from the dry, unforgiving red dirt of Durotar is never simple, but Tor'kren Farm has had a harder time than most. Situated southeast of Thunder Ridge, the homestead focuses on raising pigs in a rugged climate where feed and water are scarce. Unlike the bustling trade posts or heavily defended barracks of the Horde, the farm stands isolated and quiet, producing meager yields in the shadow of nearby bluffs. Misha Tor'kren's son Kron went west to hunt crocolisks along the Southfury River several days ago and has not returned. She had warned him about the vicious predators, but he left in anger. Now she asks passing adventurers to search for him or bring back a sign of his fate, fearing the worst but unable to begin mourning without knowing what happened.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_tor-kren-farm-239e5167f5bb37c4e4f2/1-0000.mp3", duration = 64.9665306, start = 0},
  },
}
P.transport["subzone:valley-of-honor"] = {
  hash = "5b627d",
  fullHash = "b1d730",
  text = "Valley of Honor. The Valley of Honor serves as the martial core and warrior district of Orgrimmar, nestled in the northeastern canyons of the capital. It houses the city's barracks, warrior and hunter guilds, and the battlemasters directing Horde forces across Azeroth. With active forges, training rings, and quiet waters, it is where the Horde hones its strength and remembers its martial heritage. Situated behind high canyon ridges, the Valley of Honor acts as Orgrimmar's primary military quarter. Here, the clatter of practice weaponry and the ringing of blacksmith anvils define daily life. The Hall of the Brave dominates the valley, serving as a gathering point for seasoned warriors and battlemasters coordinating campaigns across battlefronts like Alterac Valley and Warsong Gulch. Flanked by training facilities for beastmasters and hunters, the district is dedicated entirely to equipping, drilling, and mobilizing the Horde's frontline defenders. Beyond arms and drill grounds, the valley supports the logistics of war. The Burning Anvil and Red Canyon Mining supply armor and raw iron, while engineers tinker nearby in Nogg's Machine Shop. Between duties, grunts and visiting adventurers cast a line into the valley's surprisingly serene secluded pool, offering brief moments of calm away from the dusty bustle of the Valley of Strength.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-honor-48328412b6815db03b5e/1-0000.mp3", duration = 82.2857143, start = 0},
  },
}
P.transport["subzone:valley-of-spirits"] = {
  hash = "ecc975",
  fullHash = "09b7b9",
  text = "Valley of Spirits. Tucked against the western cliffs of Orgrimmar, the Valley of Spirits serves as the long-standing seat of the Darkspear tribe within the Horde's capital. Filled with thatched lodges, tiki poles, and serene pools, it offers a stark contrast to the surrounding red stone and iron-clad orcish architecture. Branching westward off the bustling Valley of Strength, the Valley of Spirits is a lush and quiet enclave dedicated to the Darkspear trolls. When the tribe settled in Durotar alongside Thrall's orcs, this tranquil pocket among the crags became their urban gathering place. Trollish craftspeople, spiritualists, and practitioners gather around its wooden bridges and winding waters, practicing their arts away from the dry heat of the main thoroughfares. Beyond its dwellings and tranquil pools, the valley hosts practitioners of magic and wild crafts. Witch doctors, herbalists, and spellcasters congregate in lodges like the Spirit Lodge and Darkbriar Lodge. Tucked toward the back is the Talon Gate, which opens directly toward the open plains of the Barrens, offering quick passage for wanderers, hunters, and travelers roaming beyond the canyon walls.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-spirits-b36f3fd5bd3bbde4daec/1-0000.mp3", duration = 68.7804082, start = 0},
  },
}
P.transport["subzone:valley-of-strength"] = {
  hash = "9cdf88",
  fullHash = "1d5c21",
  text = "Valley of Strength. The Valley of Strength is the bustling central commons of Orgrimmar, greeting all who pass through the city's towering front gates. Housing the city bank, the central auction house, and the Broken Tusk inn, it serves as the beating commercial and administrative heart of the Horde capital. Step past the fortified timber gates of Orgrimmar and you enter the Valley of Strength. Carved deep into the red canyon rock of Durotar, this valley serves as the Horde's front square. Adventurers, merchants, and warriors from all allied nations mingle across its dusty plazas, swapping war stories over flagons from the Broken Tusk inn or attending to vital trade at the central bank and auction house. It is a bustling testament to the strength and unity the orcs fought to establish in their new homeland. Beyond its defensive significance, the valley functions as the capital's foremost marketplace. Shops such as Soran's Leather and Steel Armory sell armor, while various vendors supply provisions for long treks across the Barrens. Grunts stand vigilant watch at every corner, directing newcomers and ensuring order among the diverse peoples who have taken refuge beneath Thrall's banner.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_valley-of-strength-e3ff5a37f56254845d96/1-0000.mp3", duration = 70.6873469, start = 0},
  },
}
P.transport["subzone:venomweb-vale"] = {
  hash = "2848b3",
  fullHash = "4d08ff",
  text = "Venomweb Vale. Venomweb Vale is a shadowed valley in eastern Tirisfal Glades, sitting just south of the Scarlet Monastery. Once a lush woodland teeming with game, the vale has devolved into a blighted nest overrun by aggressive, venomous arachnids. Unknown to most who pass through, it also holds an ancient legacy as the sacred meeting place of the Council of Tirisfal. Before the plague consumed Lordaeron, this valley was a peaceful retreat of lush grass and verdant trees, favored by local hunters tracking deer and rabbits. Today, rot and creeping gloom dominate the landscape. Giant, venomous spiders swarm among the trees and hollows, led by the monstrous arachnid Sri'skulk. The vale's northern edge borders the territory of the Scarlet Crusade, where darkhounds prowl near the fortified Scarlet Encampment under Lieutenant Sanders. Long before spiders infested the hollows, the vale served as the clandestine gathering ground for the ancient Council of Tirisfal. It was here that the very first Guardian of Tirisfal was empowered to battle demonic incursions. In a desperate and misguided attempt to secure their sanctuary against intruders, one council member bred and unleashed the deadly spiders that plague the basin today. An odd boulder of fool's gold—the result of a centuries-old transmutation mishap by the apprentice Falric—still marks the secluded spot where Guardian Aegwynn once convened with the Council.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_venomweb-vale-e6ffa558f006e497b70f/1-0000.mp3", duration = 88.9469388, start = 0},
  },
}
P.transport["subzone:war-quarter"] = {
  hash = "87fe29",
  fullHash = "815c7e",
  text = "War Quarter. The War Quarter is the northwestern district of the Undercity, serving as the command post and martial training ground for the Forsaken. Within its echoing stone chambers, the soldiers, priests, and crafters of Lordaeron hone their weapons and shadow magic in defense of their fledgling kingdom. It houses training halls for warriors and priests alongside weapon masters and heavy industry. Occupying the northwest sector of the subterranean metropolis, the War Quarter stands as the bastion of martial strength for the Forsaken. Beneath its gloomy stone arches, rank-and-file guards and elite champions assemble to drill in armed combat. Unlike traditional barracks of living kingdoms, this military center combines ruthless iron warfare with the chilling rites of shadow, housing an ominous Altar of Darkness where spiritual discipline merges with military ambition. Beyond housing warrior and priest guilds, the quarter functions as the heart of Undercity's wartime production. The clatter of blades and armor echoes continually against the stone, supported by the district's blacksmiths, smelters, and weapon masters. Here, iron forged deep in the earth is shaped to outfit the forces defending the ruins of Lordaeron from the Scourge and Scarlet Crusade.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_war-quarter-54ca54d7486ee543589d/1-0000.mp3", duration = 71.8367347, start = 0},
  },
}
P.transport["subzone:whispering-shore"] = {
  hash = "03a14a",
  fullHash = "f5f184",
  text = "Whispering Shore. The Whispering Shore is a somber stretch of coastline in western Tirisfal Glades, resting just north of the Solliden Farmstead. Once a tranquil and bountiful retreat for Lordaeron's fishermen, its cold waters have since been overrun by a violent tribe of murlocs. Before the Third War swept across northern Lordaeron, the Whispering Shore was renowned among locals as a favored fishing haven, celebrated for its calm waters and plentiful catches. Today, the chilling spray of the Great Sea crashes against an empty coast stripped of its peaceful past. The waters have grown cold and dark, devoid of their former bounty, and any unfortunate traveler wandering down from the hills risks being ambushed by territorial coastal dwellers. The beach is now firmly claimed by a band of hostile murlocs who ruthlessly attack anyone approaching the surf. Led by a fierce chieftain named Muad, these aquatic scavengers guard the shallows and tidal flats aggressively, posing a constant danger to nearby roads and the nearby Solliden Farmstead.",
  ["1"] = {
    {file = "Audio/Transport/full_subzone_whispering-shore-1555bc03bb6193540933/1-0000.mp3", duration = 64, start = 0},
  },
}
